quests[8192] = { id = 8192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebkosung des Animisten", progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, {class}. Zeigt keine Gnade mit den Hakkari!" }
quests[8193] = { id = 8193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglermeister", progress = "Heute zwischen 14 Uhr und 16 Uhr findet der Wettbewerb statt, der den besten Angler unter uns ermitteln wird! Seid die ERSTE PERSON, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringt und Ihr werdet der neue Meisterangler sein!\n\nFalls Ihr nicht als Erster hier sein solltet, wird Euch mein Lehrling hier mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr den Titel des Meisteranglers erwerben wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!" }
quests[8194] = { id = 8194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglerlehrling", progress = "Wir haben zwar schon einen Gewinner ermittelt, aber ich kaufe Euch dennoch Eure restlichen Leckerfische ab. Ich zahl' Euch einen angemessenen Preis, na, was sagt Ihr!", completion = "Also für mich steht der Handel, wenn Ihr damit einverstanden seid!" }
quests[8195] = { id = 8195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Razzashi, Hakkari und zulianische Münzen", progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, {name}, genauso wie den Dank unseres Stammes!" }
quests[8196] = { id = 8196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenzmangos", progress = "Die extrem wirksamen Essenzmangos wachsen auf vielen Inseln der südlichen Meere. Eine einzelne Mango erfrischt denjenigen, der davon isst, körperlich wie auch geistig. Solltet Ihr noch nie eine gekostet haben, dann erweist Ihr Euch damit keinen Dienst!\n\nHier auf der Insel verfügen wir über einen ausreichend großen Vorrat, um Euch ein paar davon im Austausch gegen eine zandalarianische Ehrenmünze geben zu können. Sprecht mit Vinchaxa, wenn Ihr wissen wollt, wie Ihr an Ehrenmünzen gelangt; ansonsten, lasst uns gleich Geschäfte machen!", completion = "Ein fairer Tausch, mein Freund. Bitte genießt die köstlichen Früchte der südlichen Meere, Ihr habt den Segen des Stammes." }
quests[8201] = { id = 8201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schädelsammlung", description = "Es ist wahr. Hakkar hat sich in Zul'Gurub eingenistet und badet in den Kräften unserer Götter. Von ihm kontrollierte Priester haben damit begonnen, die Energien unserer heiligsten Gottheiten auf den Seelenschinder zu kanalisieren. Seine Macht wird schon bald die aller Wesen in Azeroth übersteigen. Er muss aufgehalten werden!\n\nHier, nehmt diese heilige Kordel. Findet die Priester, die es wagen die Energien unserer Götter zu kanalisieren, und reiht ihre Köpfe auf dieser Kordel aneinander.\n\nKehrt anschließend zu mir zurück.", sourceObjective = "Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba.", progress = "Habt Ihr die Schädelsammlung, {name}? Wir müssen um jeden Preis verhindern, dass Hakkars Macht weiter wächst!", completion = "Ihr habt die Schädel! Euer Mut hat verhindert, dass Hakkar die Macht unserer Götter an sich reißt und ihn so geschwächt!\n\n{name}, Euer Handeln ist wahrlich heldenhaft. Mögen die Schädel dieser Verräter noch lange nachdem ihr Blut erkaltet ist, um Eure Gnade flehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8221] = { id = 8221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonderer Fisch - Kiefers Engelfisch", progress = "*Surrr* *PLIIING*\n\nIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen Kiefers Engelfisch und ich werde Euch eine feine Belohnung zuteil werden lassen. \n\n*KLING**Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung von Kiefers Engelfisch abgeschlossen.\n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*" }
quests[8222] = { id = 8222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtendes Skorpidblut", progress = "In all der Zeit, in der ich nun mit dem Jahrmarkt reise, habe ich viel über unsere Kunden gelernt. Eine Kostprobe meiner Weisheit gefällig? Kunden lieben alles, was leuchtet. Es ist völlig egal was! Ihr könntet ein abgebrochenes Stuhlbein nehmen und es zum Leuchten bringen und schon würde jedes Kind von egal wieweit her kommen, nur um darauf einen Blick werfen zu können!\n\nTja {name}, ich brauche also leuchtendes Skorpidblut. Bei den Skorpiden in Silithus, in den verwüsteten Landen oder der brennenden Steppe solltet Ihr fündig werden.", completion = "Großartig! Habt vielen Dank! Aus dem Blut werde ich eine eine exzellente Farbe mischen und damit den billigsten Tand in pures Gold verwandeln!\n\nNehmt diese Lose, {name}, danke für Eure Dienste." }
quests[8223] = { id = 8223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr leuchtendes Skorpidblut" }
quests[8224] = { id = 8224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonderer Fisch - Dezianischer Königinnenfisch", progress = "*Surrr* *PLIIING*\n\nIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen dezianischen Königinnenfisch und ich werde Euch eine feine Belohnung zuteil werden lassen. \n\n*KLING**Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung des dezianischen Königinnenfisches abgeschlossen. \n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*" }
quests[8225] = { id = 8225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonderer Fisch - Braunells blaugestreifter Flitzerfisch", progress = "*Surrr* *PLIIING*\n\nIch suche besondere Fische, um sie für Fischereimeister Bluegill zu katalogisieren. Bringt mir einen von diesen Braunells blaugestreiften Flitzerfischen und ich werde Euch eine feine Belohnung zuteil werden lassen. \n\n*KLING**Bzzzz*", completion = "*Surrr*\n\nIdentifizierung und Katalogisierung von Braunells blaugestreiften Flitzerfisch abgeschlossen. \n\nEure Belohnung ist nun erhältlich.\n\n*PLIIING-PLIIING**Bzzzz*" }
quests[8227] = { id = 8227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Maßband", description = "Inmitten von zerbrochenen Angelruten und anderen Geräten, liegt ein zusammengerolltes, seidenes Maßband. An dem Band hängt ein Schild mit der Aufschrift:\n\n\"Nat Pagle, die Düstermarschen.\"", sourceObjective = "Bringt Nats Maßband zu Nat Pagle in den Düstermarschen zurück.", progress = "Hallo da, Kleiner. Zum Angeln hergekommen?", completion = "Was, Ihr habt mein Lieblingsmaßband gefunden! Ich liebe dieses Band! Ich habe einige der größten Fische, die ich jemals gefangen habe, damit gemessen...\n\nAllerdings habe ich es in Zul'Gurub verloren... Ihr wart in Zul'Gurub? Habt Ihr den sagenumwobenen Gahz'ranka gesehen?\n\nUnd... wollt Ihr ihn fangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8228] = { id = 8228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?", sourceObjective = "Es wird diesen Sonntag einen Angelwettbewerb in Booty Bay geben! Hier sind die Regeln für den Wettbewerb, falls Ihr daran teilnehmen möchtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[8229] = { id = 8229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Könnte ich einen Flugzettel für den Angelwettbewerb bekommen?", sourceObjective = "Es wird einen Angelwettbewerb in Booty Bay geben, diesen Sonntag! Hier sind die Regeln für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[8231] = { id = 8231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wellenjagd", description = "Der Wellenhauer ist ein amphibisches Wildtier, das nur hier in Azshara vorkommt. Er ist gewandt und zäh.\n\nDie robusten, reflektierenden Schuppen eines Wellenhauers spiegeln die Stärke des Jägers wider.\n\nSpürt Wellenhauer entlang der Küste Azsharas auf, jagt sie und bringt mir ihre Schuppen.", sourceObjective = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", progress = "Seid Ihr erfolgreich gewesen?", completion = "Die Wellenhauer sind nicht einfach zu bezwingen, vor allem nicht in ihrer natürlichen Umgebung, dem Wasser.\n\nIhr habt bewiesen, dass Ihr bereit für die Jagd auf noch tödlichere Beute seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[8232] = { id = 8232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der grüne Drache", description = "Ich entsende Euch nun auf eine gefährliche Jagd. Es gilt den grünen Drachen, Morphaz, zu bezwingen und mir seinen Zahn zu bringen. Morphaz haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nWenn Ihr ihn besiegen möchtet, solltet Ihr nicht alleine gehen. Dieser Drache ist der Feind von vielen -- sucht nach anderen, die ihn ebenfalls zu vernichten suchen.\n\nDer Zahn des Drachen steht für die Macht, den ein Jäger in der Gesellschaft anderer findet. Bringt ihn zu mir und Ihr werdet viel gelernt haben.", sourceObjective = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", progress = "Ich sehe Weisheit in Euren Augen, {name}. Ist Eure Jagd beendet?", completion = "Ihr habt die alten Wege erlernt, {name}, dafür belohne ich Euch mit einem Geschenk, das aus meinen Zeiten als {class} stammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8233] = { id = 8233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein simples Anliegen", description = "Lord Jorach Rabenholdt hat nach Euch rufen lassen. Die Angelegenheit ist geheim und ich kann auch nicht mehr dazu sagen.\n\nDas Rabenholdtanwesen liegt im Vorgebirge des Hügellands -- haltet nach einem Pfad im Gebirge nordwestlich von Burg Durnholde Ausschau.", sourceObjective = "Sprecht mit Lord Jorach Rabenholdt im Rabenholdtanwesen.", completion = "Willkommen, willkommen, willkommen! Bitte, {name}, setzt Euch doch und besprecht ein simples Anliegen mit mir.\n\nSeht Ihr, {name}, ich habe erst kürzlich etwas verloren, was sehr kostbar für mich war. Um es direkt zu sagen, ich möchte es unter allen Umständen zurückhaben. Natürlich gibt es eine Belohnung für Euch, darum müsst Ihr Euch nicht sorgen! Oh ja, es ist etwas sehr Schönes.\n\nNun was sagt Ihr, {name}... seid Ihr interessiert an einem kleinen Abenteuer?", sourceObjectiveStatus = "unverified-source-field" }
quests[8234] = { id = 8234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die versiegelte azurblaue Tasche", description = "Eins nach dem anderen. Ich habe eine kleine blaue Tasche verloren, dessen Inhalt von privater Natur ist.\n\nWie dem auch sei, versucht erst gar nicht den Dieben nachzustellen, denn sie sind bereits tot. Wir wissen jedoch, dass diese Narren die Tasche nicht öffnen konnten. Sie verkauften sie also an einen Schamanen der Holzschlundfeste in Azshara als \"heiliges Relikt\". Raffiniert.\n\nIch möchte, dass Ihr nach Azshara reist und die Tasche von dem Schamanen durch Geschick... oder mittels Kraft wiedererlangt. Ich glaube mit ersterer Methode dürftet Ihr mehr Glück haben. Habt Ihr sie, bringt sie zu Erzmagier Xylem in Azshara.", sourceObjective = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist.", progress = "Kenne ich Euch?", completion = "Ah, Ihr habt die Tasche von Lord Ravenholdt. Warum habt Ihr das nicht gleich gesagt, Junge?", sourceObjectiveStatus = "unverified-source-field" }
quests[8235] = { id = 8235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Fragmente", description = "Lord Rabenholdt bittet uns beide um einen Gefallen. Er wünscht die Verzauberung von dieser Tasche zu entfernen.\n\nUnglücklicherweise hat man mir meine Abhandlungen über die Bannung von Zaubern vor kurzem entwendet, nur um von Wilden zerstört zu werden. Die Überreste sind jedoch noch immer von Wert für mich.\n\nWenn Ihr mir genug verschlüsselte Fragmente bringen könnt, kann ich die Abhandlungen wiederherstellen. Am besten tötet Ihr dafür die Wildtiere Azsharas, da diese Kreaturen die Tendenz besitzen, alles aufzusammeln, was sie so finden können.", sourceObjective = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente.", progress = "Habt Ihr genügend Fragmente gefunden, damit ich meinen Teil des Auftrages erfüllen kann?", completion = "Ihr seht aus, als hättet Ihr sogar einige der besseren Fragmente aufgelesen. Vielleicht seid Ihr doch nicht ganz so nutzlos, wie ich zuerst dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8236] = { id = 8236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der azurblaue Schlüssel", description = "Es wird einige Zeit dauern, die Fragmente zu entschlüsseln und den Zauber zu bannen. Sobald ich mein Werk vollendet habe, werde ich die Tasche Lord Rabenholdt persönlich übergeben.\n\nAllerdings gibt es da noch das Problem mit dem Schlüssel, von dem gesagt wird, er befände sich im Besitz von Morphaz, einem grünen Drachen. Er haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nVersammelt Eure getreusten Freunde und begebt Euch zu seinem Hort. Lord Rabenholdt erwartet Euch mit dem Schlüssel.", sourceObjective = "Bringt den azurblauen Schlüssel zu Lord Jorach Rabenholdt.", progress = "Die Tasche, die Erzmagier Xylem sandte, ist bereits angekommen. Habt Ihr den Schlüssel finden können?", completion = "Der Schlüssel! Und ich dachte schon, er sei für immer verloren. Bitte nehmt ein verzaubertes Gewand aus meinem Lager - sie sind nur für Schurken von außergewöhnlichem Talent und enormer Loyalität bestimmt. Es sollte schon gezeigt werden, dass Ihr, {name} niemand seid, den man unterschätzen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8237] = { id = 8237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8238] = { id = 8238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Gurubashi, Blutfratzen und Bleichborken", progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, {name}, genauso wie den Dank unseres Stammes!" }
quests[8239] = { id = 8239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Sandwüter, Schädelspalter und Blutskalpe", progress = "Ich suche nach den Symbolen der Macht, bekannt als Münzen der Stämme. Sie sind die Währung unterschiedlichster Bewohner Zul'Gurubs und eine jede ist mit subtilem, aber mächtigem Mojo erfüllt.\n\nEs gibt neun bestimmte Arten, die es zu finden gilt. Manche werden von meinen Landsmänner für unterschiedliche Rüstungen begehrt, die sie zandalarianischen Helden anbieten. Solltet Ihr welche über haben, werde ich Euch eine unserer Ehrenmünzen im Tausch gegen drei davon geben. Ihr könnt die Münzen bei Rin'wosho dem Händler verwenden; er bietet unseren Helden spezielle Gegenstände dafür an.", completion = "Ausgezeichnet - dieses Set Münzen ist eine feine Zugabe für unsere wachsende Sammlung... eine, die wir bei der Verteidigung unseres Stammes gegen die Auferstehung des Blutgottes einsetzen werden. Ihr habt Euch diese Ehrenmünze verdient, {name}, genauso wie den Dank unseres Stammes!" }
quests[8240] = { id = 8240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schmuckstück für Zanza", description = "Die Zerstörung der zahlreichen Schmuckstücke der Hakkari ist für uns von großer Bedeutung. Wir heißen sogar Außenseiter in unserem Stamm willkommen, um uns dabei in eigener Sache zu helfen!\n\nBringt was auch immer für ein Schmuckstück, das Ihr in Zul'Gurub findet, zu dem Altar von Zanza und zerstört es. Ich werde Euch nur für dieses eine Mal eine zusätzliche Ehrenmünze unseres Stammes geben; dies liegt hoch über dem, was Ihr normalerweise erhalten würdet.\n\nWerdet selbst Zeuge des Segens von Zanza!", sourceObjective = "Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sobald Ihr dies getan habt, sprecht ganz in der Nähe mit Vinchaxa.", progress = "Habt Ihr das Schmuckstück am Altar von Zanza zerstört? Erledigt dies und Ihr werdet von Zanza zweifach gesegnet!", completion = "Ausgezeichnet... jedes Schmuckstück, das wir den Dienern des Blutgotts entreißen, bringt uns alle deren endgültiger Zerstörung einen Schritt näher. Ihr ehrt die Zandalarianer und Euch selbst mit Euren edlen Taten.\n\nVergesst nicht, {name}, Ihr könnt die Schmuckstücke, die Ihr in Zul'Gurub findet, jederzeit am Altar zerstören. Ihr werdet Euch dadurch jedesmal Anerkennung und eine Ehrenmünze verdienen! Denkt einfach nur an einen freien Platz in Eurem Inventar, wenn Ihr noch keines der Stücke haben solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8241] = { id = 8241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub an feurigem Fluxus: Eisen", progress = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, {race}. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Eisenbarren.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", completion = "Es ist immer genug Platz für einen weiteren feurigen Fluxus, Junge. Immer her damit... bis ich Euch sage, dass es genug ist." }
quests[8242] = { id = 8242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub an feurigem Fluxus: Schweres Leder", progress = "Lasst uns nicht noch mehr meiner kostbaren Zeit mit Geplapper verschwenden, {race}. Wir müssen unseren schwindenden Vorrat an feurigen Fluxus wieder aufstocken.\n\nIch brauche Euch, um mir folgendes zu beschaffen:\n\n*Incendosaurierschuppen.\n\n*Schweres Leder.\n\n*Kohle.\n\nIch nehme alles was Ihr kriegen könnt!\n\nUnd seid besser schnell! Ihr wollt es Euch doch nicht mit der Bruderschaft verderben, oder?", completion = "Es ist immer genug Platz für einen weiteren feurigen Fluxus, Junge. Immer her damit... bis ich Euch sage, dass es genug ist." }
quests[8243] = { id = 8243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzas wirksame Tränke", progress = "Mit Eurem verbesserten Ruf innerhalb unseres Stammes, bekommt Ihr auch Zugang zu einigen unserer wirksamsten Tränke. Nehmt Euch in Acht... diese Gebräue sind stark im Mojo - gesegnet von Zanza und für Abenteurer jeglicher Herkunft gemacht!\n\nIch lasse Euch einen aus den drei Tränken, die ich anbiete, auswählen; im Gegenzug verlange ich eine zandalarianische Ehrenmünze. Seid Euch im Klaren, dass nur jeweils die Effekte eines Tranks zu einer beliebigen Zeit durch Euren Geist jagen können.\n\nLasst mich wissen, wenn Ihr zum Tauschhandel bereit seid!", completion = "Ein fairer Handel, mein Freund... erfreut Euch am Segen Zanzas mit unseren besten Wünschen!" }
quests[8246] = { id = 8246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Siegel der Zandalar", progress = "Für jemanden, der bei den Zandalar so angesehen ist wie Ihr {name}, habe ich etwas sehr Besonderes. Direkt aus unserer Heimat in den südlichen Meeren... die Siegel der Zandalar! Diese Siegel werden zum Aufwerten eines beliebigen Schultergegenstands, den Ihr besitzt, verwendet. Solltet Ihr nach Macht, Mojo oder Gelassenheit suchen - dann habe ich genau das, was Ihr braucht!\n\nIch gebe Euch ein Siegel Eurer Wahl im Austausch gegen fünfzehn zandalarianische Ehrenmünzen. Sobald Ihr die Münzen habt, können wir Geschäfte machen!", completion = "Ein fairer Handel, mein Freund... bitte nehmt unser Siegel mit dem Segen unseres Stammes!" }
quests[8249] = { id = 8249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderkisten benötigt", progress = "Meine Schurken müssen ihre Fertigkeiten im Schlossknacken noch verbessern und ich brauche dafür noch Schlösser mit entsprechendem Schwierigkeitsgrad -- das Zeug, das Zan für uns herstellt, taugt lediglich für totale Anfänger.\n\nIch sag' Euch was, wenn Ihr mir 5 schwere Plunderkisten besorgt, dann gebe ich Euch dafür die feinsten Wurfmesser, die in Schurkenkreisen bekannt sind.\n\nIhr könnt die Kisten öffnen und durchstöbern, aber lasst wenigstens ein paar Münzen übrig... auch ein Schurke, der sich in Ausbildung befindet, braucht etwas Motivation.", completion = "Mögen diese Messer einen Platz in jemandes Herz einnehmen.\n\nIm wahrsten Sinne des Wortes." }
quests[8250] = { id = 8250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschick der Magier", description = "Erzmagier Xylem hat seit kurzer Zeit begonnen sich umzuhören... nach jemanden mit Eurer Erfahrung.\n\nFalls Ihr ihn aufsuchen möchtet, dann könnt Ihr ihn in Azshara antreffen. Sein Turm steht hoch über den Klippen und der einzige Weg, der dort hinaufführt, ist ein Teleportationszauber, der von seinem arroganten Diener, Sanath Lim-yo, gewirkt wird.\n\nSanath kampiert unterhalb des Turms. Um ihn zu finden, müsst Ihr zu der Stelle reisen, an der sich Azsharas Hauptstraße beim Eingang zu den Ruinen von Eldarath gabelt. Geht von dort aus direkt nach Norden bis Ihr zu den Klippen kommt.", sourceObjective = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem.", completion = "<Sanath grinst Euch höhnisch an.>\n\nErzmagier Xylem wartet auf Euer Eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8251] = { id = 8251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magischer Staub", description = "Die Blutelfen in Azshara haben eine Methode entwickelt, um magische Gegenstände, die sie erhalten, zu Staub zu pulverisieren. Dieser glitzernde Staub, der so produziert wird, gleicht nicht jenem, der sich durch eine übliche Entzauberung herstellen lässt.\n\nIch habe bereits meinen Lehrling entsendet, um durch Handel diesen Staub zu erlangen, doch er wurde ohne Umschweife grausam ermordet. Dafür müssen sie bezahlen.\n\nDie Zeiten der Konversation sind vorbei, {name}. Sucht nach den Blutelfen entlang der Klippen von Azshara und wendet \"überzeugendere\" Mittel an, um an den glitzernden Staub zu kommen.", sourceObjective = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", progress = "Habt Ihr den Staub?", completion = "Gut gemacht, {name}! Ich finde es doch immer wieder beeindruckend, wie überzeugend eine Salve arkaner Geschosse sein kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[8252] = { id = 8252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Koralle der Sirenen", description = "Seht Euch nur um. Die Ruinen und Strände sind buchstäblich von den Grollflossen überrannt worden. Unlängst haben sie sich soweit mit dem Land vertraut gemacht, dass sie die seltensten und wertvollsten Elemente entdeckt haben, die in Azshara heimisch sind.\n\nGenau genommen spreche ich von der verzauberten Koralle -- sie werden aus mir unerfindlichen Gründen davon angezogen. In der Bucht gibt es nur noch sehr wenige Exemplare, die für meine Forschungen jedoch unverzichtbar sind. Ich brauche Euch, um mir 6 verzauberte Korallen von den Sirenen der Grollflossen zu beschaffen.", sourceObjective = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", progress = "Die Sirenen der Grollflossen sind überraschend starke {class}. Nicht so bewandt wie Ihr, hoffe ich doch?", completion = "Das ist eine hervorragende Korallenprobe, {name}. Euer Geschick ist äußert präzise und tödlich.\n\nGlaubt nur nicht, dass Eure Bemühungen unbemerkt geblieben sind. Vielleicht seid Ihr bereit, für einen wahren Test Eurer Fähigkeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[8253] = { id = 8253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Morphaz", description = "Es gibt einen grünen Drachen, tief im Versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt.\n\nVor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren. Der Verlust eines Lehrlings ist mir zwar nicht unbekannt, allerdings trug dieser einen arkanen Splitter von unübertroffener Größe und Qualität.\n\nBitte versammelt Eure mächtigsten Verbündeten und dringt in die Tiefen des Tempels vor. Zerstört Morphaz und entreißt ihm den arkanen Splitter aus seinem Magen.", sourceObjective = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", progress = "Habt Ihr meinen alten Feind besiegt?", completion = "Unglaublich. Der Splitter ist sogar noch mächtiger geworden. Er scheint über all die Jahre die Energie des Drachen absorbiert zu haben.\n\nEs gibt nichts mehr worum ich Euch nun bitten könnte. Meine Fähigkeit das Arkane zu wirken ist mit der Rückkehr dieses Splitters komplett wiederhergestellt. Meine erste Kreation sei die Eure, {name}, und Ihr müsst lediglich wählen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8254] = { id = 8254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarische Hilfe", description = "Es ist der Weg des Göttlichen, mit dem denen geholfen wird, die in Not sind. Das \"wie\" ist unbedeutend -- allein das \"warum\" zählt.\n\nDer Zirkel des Cenarius ist in derartigen Nöten. Sprecht mit Ogtinc, um ihnen in ihrer Notlage auszuhelfen. Er wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath in Azshara.", sourceObjective = "Sucht Ogtinc in Azshara auf.", completion = "Eure Ankunft stellt eine große Erleichterung für mich dar. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[8255] = { id = 8255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renner für einen höheren Zweck", description = "Die in Azshara lebenden Mooshufrenner sind prachtvolle Tiere, die ursprünglich aus dem Teufelswald stammen. Sie sind von Natur aus resistent gegen Krankheiten und Gifte und blieben so vor der Verderbnis in diesem Gebiet verschont. In ihrer ganzen Weisheit haben sie schlicht beschlossen, den Teufelswald zu verlassen.\n\nEs schmerzt mich von ganzem Herzen, dass ich Euch bitten muss, diese majestätischen Lebewesen für mich zu jagen. Sammelt vier Rennerdrüsen als erste Zutat für ein regenerierendes Mittel -- ein Mittel, mit dem wir den Teufelswald heilen möchten.", sourceObjective = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", progress = "Ihr seid zurück. Wart Ihr erfolgreich?", completion = "Es ist der Weg des Göttlichen, der Euch zu und geführt hat, {name}. Eure Überzeugungen interferieren nicht mit den Aufgaben, die der Herstellung des Mittels dienen.\n\nSeht Ihr, der Renner ist dem Zirkel des Cenarius heilig und das Töten aus egal welchem Grund, wie wichtig er auch sein mag, schwächt dessen Geist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8256] = { id = 8256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekret des Untodes", description = "Für dieses regenerierende Mittel braucht Ihr ein simples Rezept: ein Teil Gift, zwei Teile Heilmittel. Ihr habt bereits einen Teil des Heilmittel beschafft, nun müsst Ihr das Gift sammeln.\n\nMächtige Untote, wie die verweilenden Hochgeborenen, welche die Ruinen von Eldarath durchstreifen, sind dermaßen vom Bösen durchdrungen, dass es sich manchmal als eine Art dickflüssige, grünliche Flüssigkeit manifestiert. Unter den Lebenden ist diese Substanz als Sekret des Untodes bekannt.\n\nDie Wirksamkeit dieses widerwärtigen Elements ist derart mächtig, dass es genügen wird, wenn Ihr mir eine einfache Dosis des Sekrets bringt.", sourceObjective = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", progress = "Wir müssen das Sekret schnellstmöglich beschaffen. Habt Ihr es gefunden?", completion = "Ich nicht sagen, dass ich erfreut bin diese scheußliche Substanz zu erhalten, aber es ist wohl ein notwendigs Übel. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8257] = { id = 8257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morphaz' Blut", description = "Jetzt zum letzten Teil, dem zweiten Heilmittel.\n\nDer grüne Drache Morphaz ist dafür bekannt, gegen alle Formen von Krankheit und Gift immun zu sein - viele Druiden erlitten den Tod, um uns diese Nachricht zu übermitteln. Es gibt keine Zweifeil, dass sein Blut die für uns nötige Wirkung hat.\n\nEin Kurier des Zirkels des Cenarius wird die von Euch bereits beschafften Zutaten übernehmen, während Ihr nach der letzten sucht. Versammelt Eure Verbündeten und sucht den Unterschlupf des Drachen im Versunkenen Tempel von Atal'Hakkar auf. Bringt sein Blut anschließend zu Greta Mooshuf im Teufelswald.", sourceObjective = "Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt Greta Mooshuf im Teufelswald sein Blut. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends.", progress = "Habt Ihr das Blut von Morphaz?", completion = "Ihr habt Morphaz besiegt und uns sein Blut gebracht... ich kann diese gute Nachricht kaum fassen!\n\nWir werden sofort mit der Verarbeitung der Zutaten beginnen und die Tiere und Bäume des Teufelswalds endlich heilen. Es wird sicherlich ein ganzes Leben lang dauern, das hier Geschehene rückgängig zu machen, aber dank Eurer Hilfe verfügen wir nun über die entsprechenden Mittel.", sourceObjectiveStatus = "unverified-source-field" }
quests[8258] = { id = 8258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung durch Schattensichel", description = "Der Todesritter Schattensichel herrscht über das große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. {name}, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!", sourceObjective = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar.", progress = "Die Zeit drängt, {name} - habt Ihr der Bedrohung durch den Todesritter Schattensichel erfolgreich Einhalt gebieten können?", completion = "Das ist ein Sieg, den es auszukosten gilt, {name}! Der Untergang Schattensichels sollte den schwachen Halt, der die spirituelle Ebene zusammenhält, wieder herstellen.\n\nIhr habt die an Euch gestellten Anforderungen bei weitem übertroffen, obwohl Ihr nichts von einer Belohnung oder Entschädigung gewusst habt. Ihr seid wahrhaftig ein ehrenhafter {class}, mein Freund.\n\nIch weiß, dass der Erhalt der spirituellen Ebene Lohn genug sein sollte, aber bitte - akzeptiert dieses bescheidene Geschenk als meinen persönlichen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[8259] = { id = 8259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine angemessenere Belohnung" }
quests[8260] = { id = 8260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket von Arathor" }
quests[8261] = { id = 8261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket von Arathor" }
quests[8262] = { id = 8262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket von Arathor", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.\n\nBewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8263] = { id = 8263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basisüberlebenspaket der Entweihten" }
quests[8264] = { id = 8264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standardüberlebenspaket der Entweihten" }
quests[8265] = { id = 8265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbessertes Überlebenspaket der Entweihten", sourceObjective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, {name}. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb des Arathibecken verwendet werden können.\n\nBewährt Ihr Euch noch weiter im Arathibecken, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn Ihr unser Wohlwollen erlangt habt, sowie Verbände, wenn Ihr Euch unseren Respekt verdient habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8266] = { id = 8266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufopferungsabzeichen" }
quests[8268] = { id = 8268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufopferungsabzeichen" }
quests[8271] = { id = 8271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Sturmlanzen", sourceObjective = "Als ein Held der Stormpike, dürft Ihr Euch eines dieser erst kürzlich geplün… äh, wiederentdeckten Schätze, aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8272] = { id = 8272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held der Frostwölfe", sourceObjective = "Was ist das für ein Gefühl, {name}? Wie fühlt es sich an, die Linien des Feindes zu zerschmettern und jeglichen Widerstand auszulöschen? Es ist ein gutes Gefühl, nicht wahr?\n\nFür Eure Heldentat habt Ihr eine große Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[8273] = { id = 8273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orans Dankbarkeit", sourceObjective = "Ach das ist ja interessant! Ihr sagt, Ihr habt diese Schrifttafel auf einer kleinen, unbewohnten Insel nahe der Aussichtsklippen im Hinterland gefunden, {class}? Wirklich äußerst interessant. \n\nIch danke Euch für Eure Bemühungen in dieser Angelegenheit. Unsere dunkle Fürstin wird mit dieser Entdeckung sehr zufrieden sein. Erlaubt mir, Euch angemessen zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8275] = { id = 8275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Silithus", description = "Ihr Helden der Allianz, horcht auf! Die Bedrohung durch die Silithiden blieb zu lange unbeachtet. Ohne einen wirklichen Gegner, der sie bekämpft, haben sie sich die ganze Zeit über auf eine großangelegte Invasion vorbereitet.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen verachtungswürdigen Kreaturen den Krieg zu erklären. Alle kampftauglichen Abenteurer werden hiermit aufgerufen, sich uns anzuschließen!\n\nWartet nicht, bis es zu spät ist! Helft uns bei der Verteidigung von Azeroth! Meldet Euch für genauere Informationen bei Windruferin Prachthorn auf Burg Cenarius.", sourceObjective = "Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus.", completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8276] = { id = 8276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Silithus", description = "Ihr Helden der Horde, horcht auf! Es gibt eine Bedrohung dort draußen, die wir zu lange ignoriert haben. Erderschütterungen in der Nähe von Silithidnestern, verursacht durch massive Wanderungen dieser Biester, haben unsere Aufmerksamkeit erregt. Es scheint als bereiten sie ihre weitere Expansion vor.\n\nDer Zirkel des Cenarius sammelt seine Streitkräfte in Silithus, um diesen Silithiden den Krieg zu erklären, bevor es zu spät ist. Niemals wieder, sollen diese Biester unsere Ländereien entweihen!\n\nAlle kampftauglichen Abenteurer sollten sich umgehend bei Windruferin Prachthorn auf Burg Cenarius melden. Mögen die Silithiden endgültig besiegt werden!", sourceObjective = "Sprecht mit Windruferin Prachthorn auf Burg Cenarius in Silithus.", completion = "Hervorragend, wieder ein Rekrut, der dem Aufruf gegen die Silithiden gefolgt ist. Willkommen auf Burg Cenarius, {class}. Es freut mich zu sehen, dass unsere Abgesandten auch Helden von Eurem Kaliber erreicht haben. An diesem Ort mangelt es wahrlich nicht an Aufgaben, mit denen Ihr unsere Sache unterstützen könnt. Ich denke, Ihr werdet Euch sehr schnell als unverzichtbarer Verbündeter erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8277] = { id = 8277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tödliches Wüstengift", description = "Beetix Wankelhupf ist Euch zu Diensten! Mein Cousin Noggle hat es sich zum Lebensinhalt gemacht, seltene Kräuter für die Alchimisten der Burg Cenarius zu sammeln. Oder hatte es zumindest, egal. Er kam von seinem letzten Ausflug mit einer starken Vergiftung zurück.\n\nIch habe es geschafft die Wirkung des Gifts zu verlangsamen, aber um es vollständig neutralisieren zu können, benötige ich Giftproben von was auch immer ihn gestochen haben mag.\n\nNoggle kam aus dem Norden, daher verwette ich mein letztes Hemd darauf, dass es Steinpanzerskorpide oder Sandhuscher waren. Bringt mir ein paar Stachel und Giftzähne und ich werde versuchen ein Gegengift für ihn zu erstellen.", sourceObjective = "Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt.", progress = "Habt Ihr alle Proben zusammengesammelt? Wir können Noggle jede Minute verlieren!", completion = "Lasst uns die Daumen drücken! Hoffen wir, dass Noggle damit gerettet werden kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[8278] = { id = 8278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggles letzte Hoffnung", description = "Verflucht! Das Gegengift hat nicht gewirkt. Noggle muss von einer der stärkeren Kreaturen im fernen Süden gestochen worden sein.\n\nIch werde Euch brauchen, um dorthin zu gehen und mir noch mehr Proben zu besorgen, {name}. Das Gute dabei - da ihr Gift stärker ist, werde ich nicht so viele brauchen. Der Haken ist allerdings, dass in der südlichen Gegend mehrere Arten giftiger Kreaturen herumfleuchen und Ihr daher verschiedene Proben besorgen müsst.", sourceObjective = "Beetix Wankelhupf von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern, sowie 3 Felspirschergiftzähne für sie sammelt.", progress = "Das ist Eure letzte Chance, um Noggle zu retten! Beeilt Euch!", completion = "Ja! Es scheint zu wirken, Noggle kommt wieder zu sich. Wir sind Euch was schuldig!", sourceObjectiveStatus = "unverified-source-field" }
quests[8279] = { id = 8279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lexikon des Schattenhammerklans", description = "Der Schattenhammerklan ist nicht gerade zimperlich mit denen, die seine Reihen verlassen wollen. Sie jagen mich bis heute, als sei ich ein wildes Tier. Unnötig zu erwähnen, dass ihre Feinde meine Freunde sind!\n\nUm diese Schrifttafel zu entschlüsseln, benötige ich das Kodebuch, welches ihre Schreiber benutzt haben, um geheime Nachrichten zu dekodieren: Das Lexikon des Schattenhammerklans. Es ist dermaßen wertvoll, dass sie es in drei Kapitel aufgeteilt haben, welche an drei unterschiedlichen Orten aufbewahrt werden! Die Offiziere, denen die Teile des Lexikons anvertraut wurden, sind als Bewahrer des Schattenhammers bekannt. Sucht in den Lagern des Schattenhammerklans nach ihnen.", sourceObjective = "Bringt Ortell dem Einsiedler in Silithus die drei Kapitel des Lexikons des Schattenhammerklans.", progress = "Wer ist da? Oh, Ihr seid es! Habt Ihr schon alle Kapitel des Lexikons gefunden?", completion = "Ja! Dies sind alle Teile des Buchs! Fangen wir also an, {name}.\n\nErsetzt jedes dritte Wort, mit den Worten aus dem zweiten Kapitel… dann ersetzt die verbliebenen Worte, mit denen aus dem ersten Kapitel… Moment, war das nicht umgekehrt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8280] = { id = 8280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung der Versorgungslinien", description = "Burg Cenarius ist von außerordentlicher strategischer Bedeutung. Ich bin davon überzeugt, dass unser Sieg über die Silithiden feststeht, solange wir sie halten können. Natürlich unter der Bedingung, dass wir die Versorgung mit Nachschubgütern aufrechterhalten können.\n\nDie Sandwürmer in dieser Gegend stellen für unsere Nachschubkarawanen eine noch größere Gefahr dar als die Silithiden selbst. Erst heute Morgen verloren wir eine ganze Morgenkornlieferung an eine Gruppe Baggerschläger. Ich brauche Eure Hilfe, um die Bestände dieser Baggerschläger auszudünnen und um sicherzustellen, dass unsere Karawanen vor weiteren Überfällen sicher sind.", sourceObjective = "Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet.", completion = "Ich bin Euch sehr dankbar. Eure Bemühungen, Burg Cenarius und seine Garnison zur schützen, zeugt von wahrer Tapferkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[8281] = { id = 8281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkte Sicherheit", description = "Eure bisherigen Leistungen sind makellos, {name}. Dennoch, sind unsere Versorgungslinien noch lange nicht sicher. In Abwesenheit der Baggerschläger, werden ihre südlichen Artgenossen nach Norden drängen, um ihren Platz einzunehmen.\n\nIhr werdet eine ganze Reihe Baggerbrecher töten müssen, um diese Biester von unseren Versorgungslinien fernzuhalten.", sourceObjective = "Windruferin Prachthorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet.", completion = "Beeindruckend! Ihr habt Euch wahrhaftig als wertvoller Verbündeter in der Kriegsvorbereitung gegen die Silithiden erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8282] = { id = 8282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggles verlorener Ranzen", description = "Wo bin ich? Wo is' meine Tasche? *Keuch* Ich muss sie verloren haben, als ich vor Totenstachel, dem Riesenskorpid, geflohen bin. Bei meiner überstürzten Flucht bin ich geradewegs in ein Nest von Steinpanzerschindern gerannt.\n\nIn dem Ranzen, den ich bei mir trug, befanden sich allerlei seltene Reagenzien. Beetix und ich werden ohne sie nicht die Tränke herstellen können, die von der Burg Cenarius benötigt werden. Ich bin noch zu schwach, um wieder aufzustehen, aber ich kann es für Euch lohnend machen, wenn Ihr mir meine Reagenzien zurückbringt.\n\nIch bin Totenstachel nahe dem südlichen Gebirgszug über den Weg gelaufen, hinter Bronzebarts Lager.", sourceObjective = "Spürt Noggles Ranzen im südlichen Gebirge von Silithus auf und bringt ihn zu ihm, auf Burg Cenarius, zurück.", progress = "Habt Ihr meine Tasche noch immer nicht gefunden? Nun, ich sollte zumindest froh sein, dass das Gift zu wirken aufgehört hat.", completion = "Ja! Ihr habt meinen Ranzen zurückgebracht. Sogar all meine seltenen Reagenzien sind noch da! Ich werde für lange Zeit in Eurer Schuld stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8283] = { id = 8283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Totenstachel, Terror der Wüste", description = "Man sagt, dass sich der grausame Skorpid Totenstachel nahe des südlichen Gebirgszuges wegen erhöhter Silithidenaktivität zurückgezogen hat. Dies stellt eine große Bedrohung für Patrouillen und Expeditionen in der südlichen Gegend dar. Wer sich an dessen Vernichtung beteiligt, soll reichlich belohnt werden. Fragt bei Hauptmann Vish Kozus, ganz oben auf dem Wachturm der Burg Cenarius, wegen der Belohnung nach.", sourceObjective = "Bringt Totenstachels Zange zu Vish Kozus, Hauptmann der Wache.", progress = "Ich brauche die Zange der Kreatur als Beweis für Eure Heldentat. Keine Zange, keine Belohnung.", completion = "Ausgezeichnet! Mit dem Tod Totenstachels steht uns der südliche Gebirgszug als strategischer Pfad zum Umgehen der Silithidschwärme wieder offen. Man schätzt Eure Leistung hier sehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[8284] = { id = 8284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Schattenhammerklans", description = "Einst existierte nordwestlich von hier ein florierender Außenposten des Schattenhammers. Wenn Ihr heutzutage in diese Gegend reist, werdet Ihr dort nur Schwärme von Elementaren antreffen. Verrottete Holzpfosten und alte Zelttuchfetzen sind das Einzige, was noch auf den Standort des Lagers hinweist.\n\nVor einiger Zeit fand ich dort die Fragmente einer Tontafel, allerdings nicht genug Teile, um sie zu irgendetwas Brauchbarem zusammenzusetzen. Bringt mir die fehlenden Fragmente der Schriftafel. Vielleicht können wir so etwas Licht in die Sache bringen und herausfinden, was die Anhänger des Schattenhammerklans in Silithus gesucht haben.", sourceObjective = "Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr 8 Schrifttafelfragmente des Schattenhammerklans bringt.", progress = "Das verwüstete Lager werdet Ihr nordwestlich von hier finden. Kommt zu mir zurück, wenn Ihr alle Fragmente gefunden habt.", completion = "Wie ich es mir gedacht habe. Ich kann zwar einige der Worte auf den Schrifttafeln entziffern, jedoch scheinen sie keiner Logik zu folgen oder irgendeine Bedeutung zu haben. Das ist nicht unbedingt ungewöhnlich, da viele Sekten der Twilight-Hammer dafür bekannt sind, ihre Texte zu verschlüsseln. Wir müssen jemanden finden, der sich besser mit solchen Sachen auskennt als wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[8285] = { id = 8285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Deserteur", description = "Es gibt Gerüchte über ein Mitglied des Schattenhammerklans, das aus seiner Sekte desertiert ist und nun als Einsiedler in den Bergen südöstlich vom Südwindposten lebt. Sein Name ist Ortell. Vielleicht könnt Ihr ihn davon überzeugen, Euch bei der Entschlüsselung der Schrifttafel behilflich zu sein.\n\nNehmt die wiederhergestellte Schrifttafel mit Euch und sucht Ortell auf.", sourceObjective = "Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus.", progress = "Ihr! Wer seid Ihr? Wie habt Ihr mich gefunden? Man hat Euch doch nicht verfolgt, oder? Sprecht!", completion = "Ah, wie ich sehe, wisst Ihr einiges über meine alte Sekte. Ihr seid ein Verbündeter des Zirkels des Cenarius, richtig?\n\nIch wette, Ihr sucht nach Informationen, die Ihr gegen die Twilight-Hammer einsetzen könnt. Kommt näher, vielleicht können wir uns gegenseitig behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8286] = { id = 8286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns morgen erwartet", description = "Der Tod umarmte mich bereits als er erschien und seine Macht auf mich anwandte. Er ließ seinen Atem nur einmal über meinen versehrten Körper streichen und wartete daraufhin geduldig bis die Zeit meine Wunden geheilt hatte.\n\n\"Wenn es sein muss, wirst du für immer existieren\", sagte er, und mit diesen Worten sollte ich auf ewige Zeiten als Wächter gebunden sein.\n\nWerft jetzt einen Blick auf die Wüste. Der zweite Krieg steht uns bevor. Ihr müsst nach der Ruhestätte des Bronzeschwarms suchen. Reist zu den Höhlen der Zeit und seht nach, ob der Meister zurückgekehrt ist. Ich muss mir dessen sicher sein, bevor ich weiter vorgehe.", sourceObjective = "Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus.", progress = "Ist Anachronos zurückgekehrt?", completion = "Es ist, wie es sein sollte! Der Eine hat sich erhoben und meine Wache neigt sich dem Ende zu…", sourceObjectiveStatus = "unverified-source-field" }
quests[8287] = { id = 8287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Plan", description = "So, das sollte es gewesen sein... ziemlich wertvolle Informationen, muss ich sagen! Ich habe beobachtet, wie die Truppen des Zirkels des Cenarius in Silithus eingetroffen sind. Ich nehme an, sie planen den Schattenhammerklan aus Silithus zu vertreiben, nicht wahr? Diese Informationen sollten dabei hilfreich sein.\n\nBringt die Entschlüsselte Abschrift der Schrifttafel zu ihrem Anführer, Kommandant Mar'alith. Schon bald wird der Klan des Schattenhammers vernichtet sein und ich bin endgültig vor ihrem Zugriff sicher.", sourceObjective = "Bringt Kommandant Mar'alith die entschlüsselte Abschrift der Schrifttafel.", progress = "Was habt Ihr mir mitgebracht, {name}?", completion = "Das sind in der Tat sehr interessante Informationen, die Ihr mir da gebracht habt, {name}. Dies bringt etwas Licht in die Präsenz der Twilight-Hammer in Silithus und wird uns mit Sicherheit den Kampf gegen sie erleichtern. Eure Bemühungen sollen nicht unbelohnt bleiben, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8288] = { id = 8288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einer kann sich erheben", description = "Wir dürfen keine Zeit mehr verschwenden! Es gilt einen Helden zu finden! Die Aufgabe, die ich Euch stellen werde, würde normalerweise eine Armee erfordern, aber nur einer aus diesem Haufen von Möchtegernhelden wird sich erheben und die Bürde und Verantwortung eines Verbündeten der Brut tragen.\n\nIm Hort des Herrschers des Schwarzfels befindet sich eine äußerst grausame Bestie. Der Brutwächter Dreschbringer bewacht die Hallen des Zwists und blockiert den Weg, der in Nefarians inneres Sanktum führt. Schlachtet dieses abartige Unwesen nieder und bringt mir seinen Kopf. Seid Ihr erfolgreich, erwartet Euch die nächste Aufgabe.", sourceObjective = "Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus.", progress = "Ihr müsst Euch das Wohlwollen von Nozdormus Brut verdienen.", completion = "Habt Ihr Euch als Erster in tausend Jahren das Wohlwollen des Bronzeschwarms verdient?", sourceObjectiveStatus = "unverified-source-field" }
quests[8290] = { id = 8290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8291] = { id = 8291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt die Eindringlinge!", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, <junger/junge:c> {class}. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Kriegshymnenschlucht und verteidigt die Feste der Silberschwingen. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, {name} und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8294] = { id = 8294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8295] = { id = 8295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt die Eindringlinge der Silberschwingen", description = "Die Wildnis des Eschentals wird sich der Macht der Horde ergeben, {race}. Nichts, was die Silberschwingen tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silberschwingen und erlangt ein Ehrenabzeichen des Kriegshymnenklans. Kehrt zu mir zurück {name}, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.", sourceObjective = "Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8297] = { id = 8297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, {name}. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", sourceObjective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8299] = { id = 8299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagt die Versorgungslinien Arathors", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, {name}. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.", sourceObjective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[8301] = { id = 8301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Gerechten", description = "Die Brut Nozdormus misstraut den niederen Völkern für gewöhnlich. Ihr habt mir zwar bewiesen, dass Ihr das Zeug zu einem Helden habt, es ist jedoch an der Zeit, dies auch meinem Meister zu zeigen.\n\nDer Ashischwarm, Zoraschwarm, Regalschwarm: sie alle schwärmen rege aus und sind eine Bedrohung für unsere Existenz. Vernichtet Silithiden dieser Schwärme und nehmt Euch Fragmente ihrer Knochenpanzer. Kommt zu mir zurück, wenn Ihr vom Tragen erschöpft sein solltet, auf dass ich Euch in Eurer Entschlossenheit stärken werde.", sourceObjective = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", progress = "In ihrem Misstrauen gegenüber den sterblichen Völkern ist viel Geschichte verwurzelt; dies ist jedoch eine Geschichte, dessen Verkünden man besser der Brut überlässt, wenn es an der Zeit dafür ist.", completion = "Ihr seid nicht allein, Held. Ich werde Euch nun dazu befähigen, andere zu ernennen, die Euch bei Eurer Aufgabe behilflich sein können. Wenn Ihr der Held Eures Volkes sein sollt, dann braucht Ihr bei Euren Aufgaben und Pflichten Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8302] = { id = 8302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand der Gerechtigkeit", description = "Wählt Eure Abgesandten weise aus, Sterblicher. Jedes Mal, wenn Ihr nach Erfüllung Eurer Aufgabe zurückkehrt, dürft Ihr einen neuen Abgesandten auswählen.\n\nDas soll heißen, dass ich noch mehr der Knochenpanzerfragmente benötige. Verschwendet keine Zeit!", sourceObjective = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.", progress = "Eines Tages wird vielleicht die gesamte Burg Cenarius unter Eurer Führung stehen.", completion = "Gut gemacht, Held. Ich werde Euch nun dazu befähigen einen weiteren Agenten Nozdormus zu ernennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8303] = { id = 8303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anachronos", description = "Es ist an der Zeit, {name}.\n\nIch muss mich dafür entschuldigen, so viel vor Euch geheim zu halten. Die Feinde sind überall, selbst unter uns. Bitte, lest aus diesem Folianten und lernt. Nutzt das Wissen, das ich Euch preisgebe, und sucht nach unserem Meister.", sourceObjective = "Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid die Hoffnung Kalimdors, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8304] = { id = 8304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Natalia", description = "Meine geliebte Natalia ist verschwunden.\n\nUm die Wahrheit zu sagen, sie hat sich schon Wochen vor ihrem Verschwinden äußerst seltsam benommen. Ich habe sie mehr als einmal dabei erwischt, wie sie zu sich selber sprach, obwohl niemand in der Nähe war. Doch sie behauptete felsenfest, dass mit ihr alles in Ordnung sei und sie ihre Forschungen unbedingt fortsetzen müsste.\n\nDas letzte Mal hatte man sie gesehen, wie sie nach Süden, in Richtung Bronzebarts Lager verschwand.\n\nLeider stehen mir zu wenige Soldaten für weitere Nachforschungen zur Verfügung, {name}. Ich brauche Eure Hilfe, um die Zwerge in Bronzebarts Lager nach ihrem Verbleib zu befragen.", sourceObjective = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr die Bewohner von Bronzebarts Lager befragt. Das Lager befindet sich südlich von Burg Cenarius.\n\nKehrt zu Kommandant Mar'alith zurück, wenn Ihr die benötigten Informationen gesammelt habt.", completion = "<Kommandant Mar'alith senkt nachdenklich den Kopf>\n\nOb sie noch am Leben ist oder nicht, ich muss tun, was getan werden muss. Wir müssen sie finden. Leider binden mich meine Pflichten an diesen Außenposten. Kann ich ein weiteres Mal mit Eurer Hilfe rechen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[8305] = { id = 8305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lang Vergessenes", description = "In der südlichen Wüste von Silithus, nahe der heiligen Barriere, findet Ihr eine einzelne Kristallträne. Sie ist ein Mahnmal für all die Verluste, die wir während des Krieges der Sandstürme erlitten haben. Sucht die Träne auf und blickt in ihr Innerstes, um Erleuchtung zu erfahren.", sourceObjective = "Sucht die Kristallträne in Silithus und blickt in ihr Innerstes.", completion = "In der Nähe des Kristalls empfindet Ihr große Trauer. Dieses Gefühl ist so stark, dass Ihr glaubt, jeden Moment das Bewusstsein zu verlieren und an den Folgen der Trauer zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8306] = { id = 8306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund des Wahnsinns", description = "Ihr müsst für mich in den Bau des Regalschwarms eindringen und herausfinden, was aus meiner liebsten Natalia geworden ist, {name}. Es ist dort sehr gefährlich. Sprecht noch einmal mit den Zwergen, bevor Ihr Euch in den Schlund des Wahnsinns stürzt. Sie sollten Euch einige Tipps geben können, wie Ihr mit den Silithiden fertig werdet, die den Schwarmbau bewohnen.\n\nUnd {name}, sollten die Gerüchte stimmen und sie dem Wahnsinn anheim gefallen sein,... dann tut, was Ihr tun müsst.\n\n<Kommandant Mar'alith wendet sich von Euch ab>", sourceObjective = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet.\n\nSprecht noch einmal mit den Zwergen in Bronzebarts Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch.\n\nUnd {name}, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\"", completion = "<Kommandant Mar'alith umklammert voller Zorn seine Waffe.>\n\nC'Thun? WAS hat das alles zu bedeuten? Wer ist C'Thun? Wie kann dieser Teufel meine geliebte Natalia in dieses Monster verwandeln, von dem Ihr mir berichtet habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[8307] = { id = 8307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenrezept", description = "Sich an das Leben in der Wüste anzupassen ist alles andere als leicht. Ich vermisse nicht nur die Vögel und Bäume Auberdines, nein, diese ausgedörrte Gegend schränkt uns auch sehr in der Wahl unserer Nahrung ein. Ich versuche mehr über die Kräuter der Wüste zu lernen, aber es gibt nicht so viele.\n\nIch habe gesehen, dass Gruppen aus dem Lager des Schattenhammers westlich von hier Sandwürmer jagten. Sandwurmfleisch ist aber so bitter, ich kann mir einfach nicht vorstellen, wie sie es schmackhaft machen. Haltet Eure Augen offen, wenn Ihr zu ihrem Lager geht und lasst mich wissen, falls Ihr etwas von ihnen erfahrt.", sourceObjective = "Haltet beim Lager des Schattenhammerklans westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau.", completion = "Dieses Buch enthält einige der gängigen und sogar ein paar ungewöhnliche Rezepte. Nach kurzem Durchblättern des Buches entdeckt Ihr ein Rezept, das Sandwurmfleisch enthält.", sourceObjectiveStatus = "unverified-source-field" }
quests[8308] = { id = 8308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Brief von Brann Bronzebart", description = "An den Finder dieses Briefs,\n\nwenn Ihr dies lest, bin ich wahrscheinlich bereits tot oder werde es in Kürze sein. Die meisten meiner Männer sind schon tot.\n\nIch habe Informationen über einen Titanen entdeckt, über eine große Schlacht zwischen ihm und einem alten Gott. Ja, ein verdammter alter Gott. Wir haben einen uralten Tunnel nach Ahn'Qiraj entdeckt, dem ich jetzt folge.\n\nBringt diesen Brief in mein altes Lager. Kümmert Euch bitte um meinen Affen und gebt ihm ausreichen Wasser, Nahrung und die eine oder andere Umarmung.\n\n- Brann Bronzebart, Extremforscher\n\nP.S. Achtet auf die verrückten nachtelfischen Anbeter des alten Gottes.", sourceObjective = "Liefert Brann Bronzebarts verlorenen Brief in Bronzebarts Lager im südlichen Silithus ab.", progress = "Bei den Göttern.", completion = "Nun, jetzt wird mir einiges klar. Solltet Ihr jemals einen Weg nach Ahn'Qiraj finden, haltet Ausschau nach dem guten Brann. Ich befürchte, ohne seinen Affen ist er hilflos.", sourceObjectiveStatus = "unverified-source-field" }
quests[8309] = { id = 8309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenjagd", description = "Nach unseren ersten Streifzügen in die Schwarmbauten und dem darauf folgenden Wahnsinn der Herrin Mar'alith, haben die drei Schwarmbauten damit begonnen hunderte von Insektenkriegern auszuspucken. Die erhöhte Aktivität könnte mit den Glyphen in Zusammenhang stehen, die diese merkwürdigen Kristalle in den drei Bauten der Schwärme bedecken.\n\nWir müssen unbedingt Abpausbilder von diesen Glyphen anfertigen. Mit Hilfe der Abpausbilder gelingt es uns vielleicht, hinter das Geheimnis dieses Wahnsinns zu kommen.\n\nHier {name}, nehmt dieses Abschriftenset und begebt Euch in die Schwarmbauten. Kommt erst zu mir zurück, wenn ihr die Abpausbilder aus jedem Schwarmbau beschafft habt.", sourceObjective = "Rutgar Glyphenschnitzer in Bronzebarts Lager in Silithus möchte, dass Ihr in den Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt.\n\nBenutzt das Abschriftenset für Geologen, um Abpausbilder der uralten Glyphen herzustellen. Kehrt nach Abschluss der Aufgabe zu Rutgar Glyphenschnitzer zurück.", progress = "Wenn ihr ein durchgeknalltes Nachtelfenmädel in einem der Schwarmbauten antrefft, tut uns einen Gefallen und verpasst ihr nen' Tritt in den Hintern!", completion = "Ich werde nicht schlau aus diesen Glyphen. So etwas habe ich in meinem ganzen Leben noch nicht gesehen! Ich hoffe Frankals Forschungen können etwas Licht in das Dunkle dieser Misere bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8310] = { id = 8310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knackt den Kode", description = "Ich denke, ich kann ein Elixier entwickeln, welches uns die Entschlüsselung der Glyphen und der Sprachen der Silithiden und Qiraji sehr erleichtern wird. Was ich dafür brauche? Gut, dass Ihr fragt! Ich benötige Gehirne! Um genau zu sein, die Gehirne eines Silithiden aus jedem einzelnen Silithidenschwarm, welche die Schwarmbauten bewohnen. Bringt mir die Gehirne und Rutgars Arbeit ist vielleicht nicht umsonst gewesen.", sourceObjective = "Frankal Steinsteg in Bronzebarts Lager in Silithus möchte, dass Ihr ihm jeweils ein Silithidengehirn des Zoraschwarms, Ashischwarms und des Regalschwarms bringt. Kehrt nach der Erfüllung Eurer Aufgabe zu Frankal zurück.", progress = "Geht und spielt mit dem Affen, Junge! Ich habe keine Zeit für Belanglosigkeiten.", completion = "Fantastisch! Geht nicht zu weit weg, Junge. Vielleicht haben wir noch die eine oder andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8311] = { id = 8311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlotternachtssüßigkeiten für Jesper!", description = "Ich würde gerne während der Schlotternächte zum Süßigkeitensammeln gehen, aber ich kann nicht, ich bin krank. Wenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe! Ich glaube Ihr werdet sie mögen - sie verwandeln Euch entweder in etwas Lustiges oder Gruseliges!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Eisenschmiede verteilt auch ein kleiner Gnom namens Talvash Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", sourceObjective = "Sprecht mit den Gastwirten in Sturmwind, Eisenschmiede und Darnassus, sowie mit Talvash del Kissel in Eisenschmiede. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Jesper ins Waisenhaus von Sturmwind mit einem Marzipan aus Darnassus, einer Kaugummikugel aus Gnomeregan, Nugat aus Sturmwind und einem Pfefferminzbonbon aus Eisenschmiede zurück.", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8312] = { id = 8312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlotternachtssüßigkeiten für Spuks!", description = "Ich würde gerne während der Schlotternächte zum Süßigkeitensammeln gehen, aber ich kann nicht, ich bin krank. Wenn Ihr für mich loszieht, dann werde ich Euch Eure gesammelten Süßigkeiten gegen welche eintauschen, die ich bereits hier habe! Ich glaube Ihr werdet sie mögen - sie verwandeln Euch entweder in etwas Lustiges oder Gruseliges!\n\nAlle Gastwirte in den größeren Städten verteilen während der Schlotternächte Süßigkeiten - sprecht mit ihnen und führt ihnen vor, nach was sie Euch fragen! In Sen'jin verteilt auch ein Troll namens Kali Remik Süßes. Sobald Ihr die Süßigkeiten habt, kommt hierher zu mir zurück!", sourceObjective = "Sprecht mit den Gastwirten in Orgrimmar, Unterstadt und Donnerfels, sowie mit Kali Remik in Sen'jin. Führt ihnen vor, nach was sie im Gegenzug für die Süßigkeiten verlangen.\n\nKehrt zu Spuks ins Waisenhaus von Orgrimmar mit einem Marzipan aus Donnerfels, einer Kaugummikugel der Dunkelspeere, Nugat aus Orgrimmar und einem Pfefferminzbonbon aus Unterstadt zurück.", progress = "Habt Ihr schon alle Süßigkeiten beisammen? Ich bin traurig, dass ich wegen meinem Kranksein nicht selbst gehen kann, aber zumindest fühle ich mich ein bisschen besser, weil Ihr mir aushelft...", completion = "Wow, Ihr habt sie alle! Ihr seid großartig!\n\nDanke, dass Ihr für mich Süßigkeitensammeln und Streichespielen gegangen seid. Hier, nehmt diese Kürbisdrops - Ihr findet sie bestimmt ganz toll!\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8313] = { id = 8313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteiltes Wissen", description = "Das Rezept für die Zubereitung von Sandwürmern ist zwar lesbar, enthält aber Hinweise auf Kräuter und Gewürze, von denen Ihr noch nie gehört habt. Calandrath weiß vielleicht mehr über die Pflanzen, die in der Wüste wachsen, damit das Rezept einen Sinn ergibt.", sourceObjective = "Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius.", progress = "Habt Ihr etwas über das Rezept erfahren können? Ich hoffe, Ihr behaltet dieses Wissen nicht für Euch selbst!", completion = "Na dann sehen wir mal...\n\nDas sieht recht verständlich aus. Sie haben ihre eigenen Bezeichnungen für einige der Kräuter, aber das dürfte nicht weiter schwer zu entschlüsseln sein. Schaut, ich zeige es Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[8314] = { id = 8314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Rätsels Lösung", description = "Wir stehen kurz vor einem Durchbruch, {name}. Dank der von Euch beschafften Abpausbilder ist es mir gelungen, die Glyphen auf diesem Kristallprisma nachzubilden. Es sieht so aus, als würden sie den Qiraji und anderen unbekannten Wesen dazu dienen, mit den Silithiden zu kommunizieren.\n\nLeider ist das alles, was ich aus diesen Glyphen herauskriegen konnte. Wir müssen eine Möglichkeit finden, wie wir die in den Kristallen versteckten Botschaften freilegen können.\n\nNehmt dieses glyphenverzierte Kristallprisma und bringt es Geologin Lerchenbann auf Burg Cenarius. Sie müsste uns weiterhelfen können.", sourceObjective = "Rutgar Glyphenschnitzer in Bronzebarts Lager möchte, dass Ihr Geologin Lerchenbann auf Burg Cenarius in Silithus das glyphenverzierte Kristallprisma bringt.", progress = "Das kann doch nicht... was habt Ihr da, {name}?", completion = "Der Grund, warum die Zwerge die Glyphen nicht entschlüsseln konnten ist ganz einfach, es gibt nichts zum Entschlüsseln! Die äußere Schicht des Prismas muss exakt nach den Markierungen innerhalb des Kristalls ausgerichtet werden, damit eine Nachricht übertragen werden kann. Clever...\n\nDiese Daten zu übersetzen dürfte nicht schwer sein, doch zuerst müssen wir den Kode entschlüsseln. Was das betrifft, habe ich nur einen einzigen Anhaltspunkt auf der Oberfläche des Prismas gefunden. Vorausgesetzt, dass das Abpausbild vollständig ist, gibt es nur eine Möglichkeit... und die ist beinahe aussichtslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[8315] = { id = 8315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Anrufung", description = "Die Glyphen zeigen einen Abgesandten der Qiraji, wie er sich mit drei Silithiden, vor den Knochen eines großen Drachen, trifft. Über den Glyphen steht, soweit ich dass beurteilen kann, eine Art Kode. Es könnte gut sein, dass dieser Kode der Schlüssel zur Beschwörung des Abgesandten ist.\n\nIch werde eine Kopie des Glyphenkodes anfertigen, den Ihr vor den Knochen von Grakkarond in den Sand schreiben müsst. Wenn ich Recht habe, werden die Oberanführer in dem Glauben dort auftauchen, dass neue Informationen zur Übertragung bereit stehen. Streckt sie nieder und konfrontiert den Abgesandten. Er besitzt den Schlüssel für die Kristalle...", sourceObjective = "Geologin Lerchenbann auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft.\n\nNehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Lerchenbann zurück.\n\nFür diese Aufgabe werdet Ihr eine kleine Armee benötigen, {name}!", progress = "Nutz die Gunst der Stunde und schlagt zu!", completion = "{name}, ich halte 20.000 Jahre alte Geschichte in meinen Händen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8316] = { id = 8316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8317] = { id = 8317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küchengehilfe", description = "Das Rezept kommt gelegen. Ich mache mich besser an die Arbeit, damit ich ein paar geräucherte Wüstenknödel für heute bereit habe. Ich könnte dabei etwas Hilfe gebrauchen, Ihr werdet dafür auch belohnt werden.", sourceObjective = "Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel.", progress = "Wie steht's mit den Knödeln?", completion = "Ausgezeichnet! Ihr seid meine Rettung! Diese Knödel sind sogar richtig gut. Ich hätte von den Twilight-Hammer eigentlich nicht so etwas Schmackhaftes erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8318] = { id = 8318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Nachrichten", description = "Einige Schattenhammerkultisten tragen mit Kauderwelsch beschriftete Papiere bei sich. Ich möchte, dass Ihr mir ein paar dieser Texte bringt, {class}.\n\nIch habe zwar keine Möglichkeit, dieses Geschreibsel zu verstehen, doch das ist nicht der springende Punkt! Mit Hilfe dieser Papiere tauschen die verschiedenen Gruppierungen des Schattenhammerklans untereinander geheime Nachrichten aus. Mit jeder Nachricht, die wir aus dem Verkehr ziehen, stören wir ihre Kommunikation untereinander!", sourceObjective = "Bringt Bor Wildmähne auf Burg Cenarius 10 verschlüsselte Schattenhammertexte.", progress = "Habt Ihr die Texte?", completion = "Exzellent! Ich werde diese Texte gut verstauen, vielleicht erweisen sie sich später noch als nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[8319] = { id = 8319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Schattenhammertexte", progress = "Bringt mir weitere Texte. Es dauert nicht mehr lange, und wir haben die Twilight-Hammer aus Silithus vertrieben.", completion = "Hervorragende Arbeit! Ich werde ein gutes Wort für Euch einlegen." }
quests[8320] = { id = 8320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geolords des Schattenhammers", description = "Der Schattenhammerklan, ein dämonischer Kult, der sich den Kräften der Zerstörung verschrieben hat, errichtet seit längerem Lager in Silithus und hält dort Tag und Nacht bizarre Rituale ab. Bisher wissen wir noch nichts über ihre Pläne, allerdings vermuten wir, dass sie in irgendeiner Verbindung zu den pulsierenden roten Kristallen stehen, die man überall in der Wüste findet.\n\nAuch wenn wir ihrem Geheimnis früher oder später auf die Spur kommen werden, so müssen wir uns zunächst auf die unmittelbare Bedrohung konzentrieren. Sucht ihre Lager im Westen auf und haltet nach den Geolords des Schattenhammers Ausschau. Sie sind die Köpfe dieser Schlangen; genau dort müssen wir zuschlagen!", sourceObjective = "Tötet 10 Geolords des Schattenhammers und kehrt anschließend zu Huum Wildmähne auf Burg Cenarius zurück.", completion = "Ihr habt Eure Aufgabe mit Bravour erledigt, {name}! Der Verlust ihrer Geolords wird dem Kult der Twilight einen schweren Schlag versetzen. Ich hoffe nur, dass wir dadurch die Durchführung ihrer Pläne etwas verzögert haben…", sourceObjectiveStatus = "unverified-source-field" }
quests[8321] = { id = 8321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vyral der Üble", description = "Wir konnten eine weitere Operationsbasis des Schattenhammerklans ausfindig machen. Es ist eine gut versteckte Höhle in der nordöstlichen Ecke von Silithus, bekannt als die Kavernen des Schattenhammers. Der örtliche Anführer des Kultes, Vyral der Üble, residiert dort. Er ist Euer nächstes Ziel. Besiegt ihn und bringt mir seinen Siegelring.\n\nDie Kavernen des Schattenhammers beherbergen furchterregende Schrecken, also passt auf Euch auf! Ich wünsche Euch alles gute, {name}.", sourceObjective = "Bringt Vyrals Siegelring zu Huum Wildmähne auf Burg Cenarius.", progress = "{name}, konntet Ihr Vyral den Üblen besiegen? Habt Ihr seinen Siegelring?", completion = "Ihr habt es getan! Vyral ist tot! Das kann für die Vorhaben der Twilight-Hammer in Silithus nur den Untergang bedeuten. Sicher treiben sich noch mehr von ihnen herum, doch von dem heutigen Rückschlag, den Ihr dem Kult erteilt habt, werden sie sich nicht wieder so schnell erholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8322] = { id = 8322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faule Eier", description = "Die Menschen von Süderstade lieben ihr Bier und deshalb schätzen sie das Bier, das im Gasthaus von Süderstade serviert wird, auch besonders. Wir können von dem Chaos während der Schlotternächte profitieren und ihre letzte Ladung Bier für Wochen - wenn nicht sogar Monate, verderben!\n\nNehmt diese faulen Eier und werft sie in den großen Braukessel im Gasthaus von Süderstade. Allein Eure Anwesenheit wird für Unruhe sorgen, Ihr solltet Euch also zu verteidigen wissen!\n\nWenn Ihr Süderstade dieses unvergessliche Geschmackserlebnis überbracht habt, kommt hierher zu mir auf's Fest zurück!", sourceObjective = "Werft die faulen Eier in den großen Braukessel im Gasthaus von Süderstade.", progress = "Der Kessel ist voller Bier.", completion = "Nachdem Ihr Euch erfolgreich bis ins Gasthaus durchgeschlagen habt, werft Ihr jetzt die Eier in den großen Kessel. Ihr riecht bereits, wie der faulige Gestank die Luft verpestet...", sourceObjectiveStatus = "unverified-source-field" }
quests[8323] = { id = 8323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrer Glauben", description = "Jetzt, da sich das Lexikon des Schattenhammerklans in meinem Besitz befindet, möchte ich Euch um einen kleinen Gefallen bitten.\n\nMeine ehemalige Organisation verschickt in regelmäßigen Abständen eine verschlüsselte Postille.\n\nSollten sie bei ihrer Suche nach mir irgendwelche Fortschritte machen, wird dies mit Sicherheit im 'Wahren Glauben' bekannt gegeben werden.\n\nAbgesehen davon, dass diese Information von großer Bedeutung für mich ist, dürfte die Postille noch weitere, für Euch interessante Informationen enthalten, die ich mit Freuden teilen werde. Bringt mir einfach alle verschlüsselten Texte, die Ihr bei den Mitgliedern des Schattenhammerklans findet.", sourceObjective = "Ortell der Einsiedler möchte, dass Ihr ihm 10 verschlüsselte Schattenhammertexte beschafft.", progress = "Konntet Ihr schon einige verschlüsselte Teste ergattern? Ich kann es kaum erwarten, die aktuelle Ausgabe des 'Wahren Glaubens' zu lesen.", completion = "Hervorragend! Ich werde die Texte schnellstmöglich entschlüsseln. Sollte ich irgendetwas, dass für Euch von Interesse sein könnte finden, werde ich Euch irgendwie eine Nachricht zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8324] = { id = 8324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fester Glauben", progress = "Konntet Ihr noch mehr verschlüsselte Texte finden? Die Entschlüsselung wird noch eininge Zeit brauchen, also bringt mir ruhig einen großen Stapel Texte.", completion = "Hervorragend! Ich kann es kaum erwarten, sie zu lesen. Hört nicht auf und bringt mir auch weiterhin alle verschlüsselten Texte, die Ihr findet." }
quests[8325] = { id = 8325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung der Insel der Sonnenwanderer", description = "Je früher Ihr mit Eurer Ausbildung anfangt, {name}, umso besser für uns alle. Wir können uns keine Fehler erlauben, also hört gut zu.\n\nDie brennenden Kristalle - die grünen, schwebenden Objekte westlich des Sonnenturms hier - wurden lange Zeit als Energiequelle für die Experimente der Insel verwendet. Die Manawyrm waren ihre Wächter, aber der Einmarsch der Geißel in Quel'Thalas hat sie auf Grund unserer mangelnden magischen Kontrolle über sie fehlgeleitet.\n\nUns bleibt keine andere Wahl, als sie für die Wiedereroberung der Insel in ihrer Zahl zu reduzieren. Kehrt nach Beendigung Eurer Arbeit zu mir zurück.", sourceObjective = "Tötet 8 Manawyrm; sie halten sich rund um die brennenden Kristalle auf, die man nahe des Turms und des Vorbaus findet. Kehrt zu Magistrix Erona beim Turm auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt.", completion = "Ihr habt Eure erste Aufgabe erfolgreich gemeistert; lasst Euch dafür danken. Ein derartiger Erfolgt bestärkt mich in meinem Glauben, dass Ihr Euch besser anstellen werdet als diese jungen Blutelfen, die sich nicht an die Vorgaben ihrer Meister gehalten haben. Weitere Leistungen wie diese werden in Zukunft belohnt werden - nicht nur mit Wissen, sondern auch mit greifbaren Belohnungen.\n\nDennoch, Eure Arbeit hier ist nicht getan. Es gibt noch viel zu lernen, mein Kind...", sourceObjectiveStatus = "unverified-source-field" }
quests[8326] = { id = 8326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedauerliche Maßnahmen", description = "Eure Bemühungen haben uns etwas erkennen lassen, von dem ich hoffte, es wäre nicht wahr. Die unkontrollierte Macht der brennenden Kristalle hat einen viel größeren Teil des natürlichen Gleichgewichts der Insel durcheinander gebracht als ich vermutet habe. Wir müssen jetzt leider bedauerliche Maßnahmen ergreifen, um die Kontrolle wiederzuerlangen.\n\nDie Luchse aus der Umgebung sind dem Einfluss der Kristalle erlegen und müssen bekämpft werden. Bringt mir ihre Halsbänder, {name}. Noch kann ich vielleicht einen Magieschutz anfertigen, der manche wieder dem Einfluss entziehen kann.", sourceObjective = "Sammelt 8 Luchshalsbänder von erlegten Bachtatzenluchsen und Bachtatzenjungen ein. Kehrt zu Magistrix Erona auf der Insel der Sonnenwanderer zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = "Es bereitet mir keine Freude, Euch um die Vernichtung dieser Kreaturen zu bitten. Wir haben in der Vergangenheit stets in Harmonie mit den Geschöpfen des Waldes gelebt, aber heute ist es anders. Der Grundsatz der Sin'dorei lautet Überleben; vergesst das nie.", completion = "Der Turm und die unmittelbare Umgebung sollten jetzt einigermaßen sicher sein, zumindest vorerst. Dank Euch haben wir an Sicherheit gewonnen, aber es gilt die Kontrolle über die ganze Insel wiederzuerlangen, wenn wir hier auf Dauer überleben wollen. Es wird weitaus mehr verlangen, als Manawyrms und Luchse auszulöschen.\n\nNehmt dies, {name} - es wird Euch bei Euren künftigen Taten sicherlich von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8327] = { id = 8327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichterstattung an Lanthan Perilon", description = "Erstattet meinem Assistenten Lanthan Perilon Bericht. Er wird Euch sagen, was es als Nächstes zu tun gilt. Während wir hier am Sonnenturm weiterhin über die brennenden Kristalle walten, werdet Ihr Euch auf eine dringendere Angelegenheit bezüglich der Akademie von Falthrien konzentrieren. Lanthan wird Euch alles erklären, wenn Ihr mit ihm sprecht.\n\nGeht einfach von hier aus gen Westen entlang des Pfads, Ihr solltet ihn in der Nähe antreffen.\n\nViel Glück, {name} - jeglicher Erfolg soll belohnt werden.", sourceObjective = "Sprecht mit Lanthan Perilon auf der Insel der Sonnenwanderer. Er steht in der Nähe des Pfads, der vom Sonnenturm Richtung Westen verläuft.", completion = "Magistrix Erona sagte mir bereits, dass Ihr schon bald hier sein würdet, {name}. Es steht sehr schlecht um die Akademie von Falthrien, das große schwebende Gebäude mit den kunstvollen Türmchen, das westlich von uns liegt. Ihr werdet den Rückeroberungsversuch gegen einen Getriebenen anführen - einen Blutelfen, der ihrer erbärmlichen Gier auf ewig verfallen ist.\n\nIch hoffe Ihr seid bereit. Dies wird Euch nicht nur einiges über Gefahren lehren, sondern auch etwas über das Schicksal, das Euch ereilt, wenn Ihr Eure Existenz leugnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8328] = { id = 8328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Magier", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Magier hier auf der Insel der Sonnenwanderer ist Julia Sonnensturm. Sprecht mit Julia, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nJulia - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Julia Sonnensturm - der Magielehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", completion = "Ah, {name} - Ihr gehört wohl zu den neuen Magiern hier auf der Insel, ja? Nun, Ihr seid hier richtig. Wenn es die Arkanbeherrschung ist, nach der Ihr sucht, dann kann ich Euch dieses Wissen vermitteln - solange Ihr über die erforderlichen Mittel verfügt, um die Ausbildungskosten zu tragen und solange Ihr Euch auf das konzentrieren könnt, was ich Euch lehre.\n\nLasst uns anfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8330] = { id = 8330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solanians Habe", description = "Bei dem Chaos hier beim Sonnenturm, habe ich es nicht geschafft, all mein Hab und Gut zusammenzusammeln, das ich an verschiedenen Plätzen auf der Insel gelassen habe. Ich muss hier beim Sonnenbrunnen weiterhin Wache halten, aber könntet Ihr vielleicht meine Sachen an meiner Stelle suchen gehen?\n\nIch brauche meine Seherkugel, meine Rolle der Geißelmagie und mein Tagebuch. Nutzt diesen Ranzen für zusätzliches Gepäck, da die Dinge etwas sperrig sind. Bringt sie zu mir zurück und ich gebe Euch dafür etwas im Austausch - für Eure Mühe, versteht Ihr? Den Ranzen könnt Ihr dann auch behalten!", sourceObjective = "Sammelt Brunnenbehüter Solanians Seherkugel, seine Rolle der Geißelmagie und sein Tagebuch ein. Ihr findet die Gegenstände auf der Insel der Sonnenwanderer bei dem Tümpel, dem Brunnen und bei einem der brennenden Kristalle. Bringt sie zu dem Brunnenbehüter oben im Sonnenturm auf der Insel der Sonnenwanderer, sobald Ihr alle gefunden habt.", progress = "Habt Ihr meine Sachen finden können? Sobald wir unsere Herrschaft über die Insel der Sonnenwanderer wiedererlangt haben, werde ich sie für meine Arbeit benötigen. Vorerst muss ich noch über den Sonnenbrunnen wachen... oder was davon übrig ist.", completion = "Gut gemacht - ich wusste, dass Ihr für diese Aufgabe geeignet sein würdet. Sobald wir uns auf der Insel wieder frei bewegen können, werde ich meine Sachen gut einsetzen.\n\nWie ich schon sagte, Ihr könnt den Ranzen behalten. Außerdem könnte auch dieses Rüstungsteil von Nutzen für Euch sein. Betrachtet es als großzügige Entlohnung für eine einfache Pflichterfüllung!", sourceObjectiveStatus = "unverified-source-field" }
quests[8331] = { id = 8331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aurel Goldblatt", description = "{name}, wir hatten angenommen, dass wir die Operationen des Schattenhammerklans in Silithus verlangsamt haben... bedauerlicherweise lagen wir falsch. Durch verschiedene Unternehmungen gegen den Kult, haben wir herausgefunden, dass eine noch viel dunklere Macht hinter dem Schattenhammerklan steht, der sogenannte Abyssische Rat. Er kontrolliert den Kult über die arkanen Windsteine, die in den Lagern der Schattenhammerkultisten postiert sind. Daher, {name}, werdet Ihr als nächstes gegen den abyssischen Rat ins Feld ziehen.\n\nSprecht mit Aurel Goldblatt im östlichen Teil von Burg Cenarius. Für unseren nächsten Schachzug werden wir ihre Hilfe benötigen.", sourceObjective = "Sprecht mit Aurel Goldblatt auf Burg Cenarius.", completion = "Guten Tag, {name}. Mir wurde gesagt, dass Ihr Euch mit dem abyssischen Rat messen wollt? Wenn dem so ist, hört mir genau zu…", sourceObjectiveStatus = "unverified-source-field" }
quests[8332] = { id = 8332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürsten des Rates", description = "Wir glauben, es sollte möglich sein, mit Hilfe eines der Windsteine, einen der Fürsten des Abyssischen Rates in eine Falle zu locken. Um das zu bewerkstelligen, werdet Ihr den Rat mit einem der Windsteine kontaktieren müssen. Dann gilt es, Euer Gegenüber davon zu überzeugen, dass Ihr ein Offizier, mittleren Ranges, des Schattenhammerklans seid.\n\nFür Euren Täuschungsversuch werden wir auf jeden Fall die Nachbildung eines Standesmedaillons des Schattenhammerklans benötigen. Ich kann ein solches Medaillon anfertigen, allerdings brauche ich dafür einen großen glänzenden Splitter und das Wappen eines abyssischen Templers.\n\nBringt mir diese Komponenten und ich fertige Euch das Medaillon an.", sourceObjective = "Bringt Aurel Goldblatt auf Burg Cenarius 1 großen glänzenden Splitter und 3 Abyssische Wappen.", progress = "Ah, {name}, habt Ihr den Splitter und die Wappen? Nur mit diesen Komponenten kann ich Euch das Standesmedallion eines Twilightkultisten anfertigen.", completion = "Ah, sehr gut. Das Medallion ist fast fertiggestellt. Wartet kurz, während ich Eure Komponenten in das Medallion einarbeite…\n\nDas hätten wir. Hier ist das Medallion, {name}.\n\nIhr müsst das Medallion tragen, wenn Ihr einen der Windsteine der Twilight-Hammer aktiviert. Solange Ihr das Medallion und den restlichen Twilightzierat tragt, wird Euch der abyssische Rat für einen ihrer niederen Kultisten halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8333] = { id = 8333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Standesmedaillon", progress = "Falls Ihr ein weiteres Standesmedaillon eines Twilightkultisten braucht, helfe ich Euch gerne weiter. In jedem Fall benötige ich jedoch einen weiteren glänzenden Splitter und einige abyssische Wappen…", completion = "Hier, nehmt es, {name}. Ein weiteres Standesmedaillon der Twilight. Nutzt es weise, und alles Gute für Euren Kampf gegen den abyssischen Rat!" }
quests[8334] = { id = 8334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressivität", description = "Bevor ich Euch zur Akademie aussende, möchte ich, dass Ihr Euch um eine andere Aufgabe kümmert, die es sofort zu erledigen gilt. Einst halfen uns die Borklinge, die Pflanzenwelt der Insel der Sonnenwanderer zu erhalten, aber jetzt sind uns diese Bestien außer Kontrolle geraten. Helft uns so schnell wie möglich bei ihrer Vernichtung, aber seid gewarnt - der Verlust ihrer Kontrolle hat sie äußerst aggressiv werden lassen. Es ist diese Angriffslust, die uns zwingt, diese einst friedlichen Untergebenen zu zerschlagen.\n\nEs bereitet mir keine Freude, Euch um diesen Gefallen zu bitten, aber es geht nun mal ums Überleben. Ich werde später trauern.", sourceObjective = "Tötet 7 Borklinge und 7 wilde Borklinge. Kehrt dann zu Lanthan Perilon auf der Insel der Sonnenwanderer zurück.", completion = "Der Tod der Borklinge macht mich zwar nicht glücklicher, aber es beweist mir, dass Ihr für die wichtigste Aufgabe hier auf der Insel der Sonnenwanderer bereit seid. Nehmt dies und setzt es mit Bedacht ein; Ihr werdet gute Waffen und einen scharfen Verstand für Euren nächsten Auftrag brauchen. Es liegt an Euch, ob wir die Kontrolle über die Insel erfolgreich wiedererlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8335] = { id = 8335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felendren der Verbannte", description = "Einer unserer Verräter haust oben in der Akademie von Falthrien.\n\nFelendren ist sein Name. Er wurde aus dem Reich der Blutelfen verbannt, da er die Warnungen unserer Lehrer und Ältesten missachtet hat. Er ist der Schlimmste unserer Art, da er nur nach der Befriedigung seines unstillbaren Magieverlangens strebt. Er hat sich der Kontrolle verweigert und ist nur noch ein Schatten seines einstigen Selbsts - einer Getriebenen - und er stellt eine Bedrohung für den Sonnenturm dar.\n\nVernichtet ihn und die Gespenster, die er sich als Diener zu Nutzen macht.", sourceObjective = "Tötet 8 Arkangespenster, 2 besudelte Arkangespenster und Felendren den Verbannten. Ihr findet sie in der Akademie von Falthrien. Bringt Felendrens Kopf zu Lanthan Perilon auf der Insel der Sonnenwanderer.", progress = "Lasst Euch gewarnt sein - Felendren der Verbannte ist nur das Anzeichen eines viel größeren Problems. Sein Untergang wird lediglich unsere momentanen Schwierigkeiten lösen. Allen Blutelfen könnte das gleiche Schicksal wie ihn ereilen, sollten wir unserem Verlangen gänzlich erliegen.", completion = "Felendrens Kopf... Ihr verdient Lob, {name}. Wo andere, wie Felendren, versagt haben, habt Ihr Euch erfolgreich gezeigt. Vielleicht seid Ihr wirklich bereit, ein gleichgestelltes Mitglied der Blutelfen zu werden.\n\nEuer Erfolg hier beweist, dass Ihr den größeren Bedrohungen Immersangs gefeit seid... und glaubt mir, es gibt genug davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[8336] = { id = 8336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für eine Handvoll Fragmente", description = "Es ist eine Schande, dass wir die Kontrolle über so viele Kreaturen hier auf der Insel verloren haben. Es war einst ein ruhiger Ort der Studien und Forschungsarbeiten. Jetzt können wir uns nur noch hüten, damit wir von unseren eigenen Kreationen nicht angegriffen werden!\n\nIch biete Euch einen magischen Segen an, wenn Ihr für mich etwas einsammelt. Bringt mir eine Hand voll Arkanspäne von den Mana benutzenden Kreaturen der Insel der Sonnenwanderer und ich wirke einen Zauber auf Euch, welcher Eure weiteren Abenteuer immens erleichtern wird.", sourceObjective = "Sammelt 6 Arkanspäne und bringt sie zu Arkanist Ithanas auf der Insel der Sonnenwanderer. Derartige Fragmente findet man bei allen Mana benutzenden Kreaturen auf der Insel.", progress = "Einst waren uns viele der Lebewesen auf dieser Insel friedlich gesinnt, unsere Magie hielt sie in einem permanenten Zustand der Kontrolle. Doch mit der Zerstörung des Sonnenbrunnens durch die Geißel verloren wir auch unsere Kontrolle über sie. Die Arkanspäne sind das letzte Überbleibsel unserer damaligen Beherrschungsmagie und als solche, können sie uns vielleicht bei der Erschaffung eines neuen Artefakts helfen, mit dessen Macht wir die Kontrolle zurückerlangen werden.\n\nNoch wichtiger, mit Hilfe der Fragmente könnten wir herausfinden, unter welchem Fluch diese Insel wirklich leidet...", completion = "Großartig, die werden ihren Zweck erfüllen! Ursprünglich habe ich diesen abgelegenen Ort aufgesucht, um in aller Ruhe nachzudenken und zu erforschen, unter welchem Fluch die Insel der Sonnenwanderer leidet. Eine der Möglichkeiten, die ich in Betracht zog, war das Sammeln der Arkanspäne von den Wildtieren auf der Insel. Mit ihnen wollte ich experimentieren, um eine mögliche Ursache zu entdecken.\n\nWie auch immer, ich werde mich weiter auf meine Forschungen konzentrieren. Erlaubt mir, diesen Zauber auf Euch zu wirken. Ich denke, Ihr werdet ihn sehr nützlich finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[8338] = { id = 8338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelter Arkanspan", description = "Das Fragment kristallisierten Manas, das Ihr bei dem Körper des besudelten Arkangespensts gefunden habt, ist äußerst sonderbar. Es ist anders als die Fragmente, die Ihr vielleicht sonst gesehen habt. Es sieht so dunkel und unheimlich wie das Gespenst, von dem Ihr es habt, aus. Hält man es in der Hand, spürt man bereits etwas unnatürlich Bedrohliches.\n\nArkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer könnte für das Fragment vielleicht Verwendung finden.", sourceObjective = "Bringt den besudelten Arkanspan zu Arkanist Helion beim Vorbau des Sonnenturms auf der Insel der Sonnenwanderer.", progress = "Ich entnehme Eurer Haltung, dass es um etwas Dringliches geht. Kann ich Euch irgendwie behilflich sein?", completion = "Das ist... äußerst interessant. Mit interessant meine ich beunruhigender als alles andere.\n\nUnser Bestreben nach der Zerstörung des Sonnenbrunnens wieder die Kontrolle über diese Insel zu erlangen, war eine Herausforderung. Ich vermute, welch Übel auch immer der Grund für diese Verderbnis der Insel ist, dass das Fragment uns weitere Auskünfte über dessen Ursprung geben kann.\n\nEs war weise von Euch, damit zu mir zu kommen, {name}. Nehmt dies als Vergütung für Eure Mühen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8341] = { id = 8341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lords des Rates", description = "Einen Lord des abyssischen Rates kann nur durch einen großen Windstein herbeigerufen werden und nur den höchstdekorierten Ratsmitgliedern des Schattenhammerklans ist es erlaubt mit den Lords in Kontakt zu treten. Doch... ich habe einen Weg gefunden, um Eure Verkleidung anzupassen und somit die abyssischen Lords zu täuschen!\n\nDazu benötigen wir einen Herrschaftsring, welcher nur von den höchsten Mitgliedern des Kultus getragen wird. Ich kann Euch einen Ring anfertigen, wenn Ihr mir einige große glänzende Splitter und ein paar abyssische Siegel bringt.", sourceObjective = "Bringt Aurel Goldblatt auf Burg Cenarius 5 große glänzende Splitter und 3 abyssische Siegel.", progress = "Habt Ihr die Splitter und Wappen, {name}? Ich brauche sie, um den Herrschaftsring anzufertigen.", completion = "Habt Dank. Gebt mir einen Moment Zeit, um den Ring zu vollenden…\n\nSo, das sollte es gewesen sein. Denkt daran, den Ring, das Standesmedallion und den restlichen Twilightzierat anzulegen, bevor Ihr einen der großen Windsteine aktiviert. Wenn Ihr alles richtig gemacht habt, werden die Mitglieder des abyssischen Rates Euch für einen ihrer Gefolgsleute halten. Anschließend sollte es Euch gelingen, einen von ihnen in die Falle zu locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[8342] = { id = 8342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrschaftsring des Schattenhammerklans", progress = "{name}, wenn Ihr Euch noch einmal um den Hohen Abyssischen Rat bemühen möchtet, dann werdet Ihr einen weiteren Herrschaftsring des Schattenhammerklans benötigen. Bringt mir mehr Splitter und Siegel und ich fertige Euch einen weiteren an.", completion = "Ah, ich sehe, dass Eure Überzeugungen stark sind. Nicht viele werden diesem Rat von Unmenschen gegenüberstehen!\n\nHier ist Euer Ring, {name}. Möge Euer Wille und Euer Glück beständig sein." }
quests[8343] = { id = 8343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldblatts Entdeckung", description = "{name}, Aurel Goldblatt glaubt einen Weg gefunden zu haben, eines der führenden Mitglieder des Abyssischen Rates zu beschwören und zu besiegen. Diese Aufgabe wird äußerst gefährlich werden und ihr genießt den größten Respekt innerhalb des Zirkels des Cenarius. Daher glauben wir, dass wenn es jemanden gibt, der diese schwere Prüfung meistern kann, dann seid ihr es.\n\nMöge Euch das Schicksal gnädig sein, {name}! Sprecht mit Aurel, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Aurel Goldblatt auf Burg Cenarius.", completion = "Was Huum sagt, entspricht der Wahrheit. Ich denke, ich weiß, wie ich einen der Lords des abyssischen Rates beschwören kann! Ich werde es Euch erklären, hört genau zu…", sourceObjectiveStatus = "unverified-source-field" }
quests[8344] = { id = 8344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zur Macht", description = "Erhört meine Worte, Kind - diese Insel ist von einem Makel behaftet, der mächtiger als die Überbleibsel der Geißel ist.\n\nIch glaube, dass auf der Insel eine wirklich dämonische Präsenz vorherrscht.\n\nWestlich von hier liegen die Türme der Akademie von Falthrien. Die Arkangespenster, die dort hausen, sind der Schlüssel zu der dämonischen Machtquelle. Bringt mir Essenzen von besudelten und unbesudelten Gespenstern.\n\nIm Austausch für Euren Gehorsam, werde ich Euch lehren, wie man einen Wichtel als Begleiter beschwören kann - Euren ersten von vielen als Hexenmeister.", sourceObjective = "Bring 4 Essenzen eines Gespenstes und 1 Essenz eines besudelten Gespenstes zu Beschwörer Teli'Larien beim Sonnenturm auf der Insel der Sonnenwanderer.", progress = "Die Essenzen der Gespenster werden mir als Grundlage für meine Experimente dienen. Es ist, wie in Eurem Leben als Hexenmeister auch, wichtig, vom dem zu lernen, was wir in der Welt finden... bevor wir es nach unserem Willen formen. Da Dämonen eine der mächtigsten Machtquellen darstellen, stellt eine derartige Präsenz auf der Insel einen wahren Segen dar.\n\nNun... einen Segen für uns Hexenmeister.", completion = "Gut gemacht! Ja, diese Essenzen sollten für den Beginn meiner Experimente ausreichen. Ich habe so ein Gefühl, als würde diese besudelte Essenz der Schlüssel sein... der Schlüssel, den ich erwähnte.\n\nEs ist äußerst ratsam für einen jungen Hexenmeister, die Anweisungen seines Meisters zu befolgen. Wie versprochen, die Belohnung für Euren Gehorsam und die meisterliche Erfüllung Eurer Aufgabe - das Wissen zur Beschwörung und Bindung Eures eigenen Wichtels.\n\nSetzt ihn weise ein {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8345] = { id = 8345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein von Dath'Remar", description = "Tag für Tag stehe ich hier, beobachte, warte. Man hat mich beschuldigt, zu tief in unserer Vergangenheit zu graben, während mein Blick zum Horizont gerichtet ist. Ich glaube jedoch fest daran, dass jeder Besucher dieser Insel diejenigen ehren sollte, die alles dafür geopfert haben, damit andere fortfahren können.\n\nDath'Remar Sonnenwanderer war unser erster König. Er führte uns durch den Mahlstrom von Kalimdor hierher.\n\nSucht seinen Schrein im Westen auf und kehrt erst dann zu mir zurück, wenn Ihr die dort angebrachte Tafel zu seiner Ehre gelesen habt.", sourceObjective = "Lest die Tafel am Schrein von Dath'Remar und kehrt anschließend zu Brunnenbehüter Solanian beim Sonnenturm auf der Insel der Sonnenwanderer zurück.", completion = "Ah, {name} - Danke, dass Ihr mir von Euren Beobachtungen beim Schrein von Dath'Remar erzählt habt. Euer Forscherdrang hat uns und Euch heute ausgezeichnete Dienste geleistet. Ich bin sicher, er wird Euch nicht nur hier, sondern in ganz Azeroth von Nutzen sein.\n\nWas Eure merkwürdigen Empfindungen beim Schrein angeht, ich denke, dass sich dort ein Teil der Verderbnis eingenistet hat, die die gesamte Insel der Sonnenwanderer bedroht. Wir werden die Sache im Auge behalten; danke, dass Ihr uns alarmiert habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[8346] = { id = 8346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstillbarer Durst", description = "Wenn es eine Lektion von Eurer Zeit auf der Insel der Sonnenwanderer gibt, die Ihr niemals vergessen dürft, dann ist es diese: Verliert unter keinen Umständen die Kontrolle über Euer Verlangen nach Magie. Dieser Durst ist unstillbar, {name}. Nutzt den Manadurst, um Energie zu absorbieren, und verwendet den arkanen Strom, um sie in der von Euch gewünschten Form wieder freizulassen. Begeht Ihr dabei einen Fehler, werdet Ihr zu einem Getriebenen... hoffnungslos abhängig und dem Wahnsinn verfallen.\n\nSucht auf der Insel nach Kreaturen, die Mana verwenden, und fokussiert Euren Manadurst auf sie. Lernt Euer Verlangen nach Magie zu kontrollieren. Wenn Ihr Euch ausreichend genährt habt, kehrt zu mir zurück.", sourceObjective = "Verwendet die Fähigkeit Manadurst sechsmal auf Kreaturen, die über Mana verfügen und kehrt anschließend zu Arkanist Helion zurück.", completion = "Ihr habt Euch heute bewiesen, {name}. Eurer Wille zu lernen zeigt, dass Ihr Euch sehr wohl gegenüber dem endlosen Verlangen, welches jeden Blutelfen beherrscht, durchsetzen könnt.\n\nRuht Euch nicht auf Euren Lorbeeren aus, sondern versucht zu meistern, was Ihr gelernt habt. Nur durch Tatendrang können wir als Volk überleben.\n\nNehmt dies - es wird Euch von Nutzen sein. Geht nun und macht unserem Volk noch einmal Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[8347] = { id = 8347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Kundschafter", description = "Magistrix Erona möchte, dass Ihr Euch nach Silbermond begebt, um die dortigen Bestrebungen zur Wiedereroberung zu unterstützen... allerdings gilt es vorher noch, etwas bei der Akademie von Falthrien zu erledigen. Ihr habt uns nicht enttäuscht, {name}.\n\nAuf Eurem Weg zum Falkenplatz südlich von hier solltet Ihr mit Kundschafterin Alarion sprechen. Sie ist nicht weit der Brücke.\n\nDie Kundschafter kümmern sich um den Warenverkehr zwischen hier und dem Landesinneren der Insel, und da Ihr Eure Tatkräftigkeit eindrucksvoll unter Beweis gestellt habt, denke ich, dass sie Eure Hilfe sicherlich sehr begrüßen werden.", sourceObjective = "Sprecht mit Kundschafterin Alarion nahe der Brücke, die in den Süden der Insel der Sonnenwanderer führt.", completion = "Oh, hallo {class}! Ich hörte schon, dass einer von Magistrix Eronas findigen Blutelfen sich auf den Weg hierher gemacht hat, um uns Kundschaftern ein wenig zur Hand zu gehen. Etwas Hilfe kommt uns sehr gelegen, insbesondere von jemand so tatkräftigem, wie Euch.\n\nSeid Ihr bereit, ein oder zwei Botengänge für uns zu erledigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8348] = { id = 8348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Fürsten", description = "Huum hat mir erzählt, dass Ihr herausbekommen habt, wie man einen der abyssischen Fürsten herbeiruft? Eine beeindruckende Leistung, muss ich sagen.\n\nWisst Ihr, was noch beeindruckender wäre? Wenn Ihr es fertig bringt, eines dieser Dinger zu erledigen. Das sollte einen bleibenden Eindruck bei ihren Gefolgsleuten hinterlassen, wenn Ihr wisst, was ich meine. Bringt mir das Siegel des Besiegten, als Beweis Eurer Tat.", sourceObjective = "Bringt Bor Wildmähne auf Burg Cenarius das abyssische Siegel.", progress = "Wie lief es mit dem abyssischen Fürsten? War er ein harter Brocken?", completion = "Seit Ihr Burg Cenarius betreten habt, war mir klar, dass Ihr ein mächtiger {class} seid. Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[8349] = { id = 8349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor Wildmähne", description = "Nun, da Ihr ein Medaillon habt und in der Lage seid, einen abyssischen Fürsten herbeizurufen, sprecht mit Bor Wildmähne. Er wird Euch mit einer Aufgabe, die sich gegen den Abyssischen Rat richtet, beauftragen.\n\nViel Glück, {name}. Falls Ihr weitere Medaillons braucht, kehrt zu mir zurück.", sourceObjective = "Sprecht mit Bor Wildmähne auf Burg Cenarius.", completion = "Es freut mich, Euch wiederzusehen, {class}! Gut, wie ich sehe, habt Ihr Euch eine Medallion anfertigen lassen. Für Eure nächste Aufgabe werdet Ihr sie brauchen…", sourceObjectiveStatus = "unverified-source-field" }
quests[8350] = { id = 8350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfolgreiche Lieferung", description = "Der Tod eines weiteren Kundschafters ist eine wahre Tragödie, aber es ist ein Risiko, das wir alle in Kauf nehmen, wenn wir einen Auftrag annehmen. Magistrix Erona beim Sonnenturm möchte, dass dieses Päckchen schnellstmöglich zum Gasthaus beim Falkenplatz geliefert wird.\n\nWir haben nur noch wenige Leute und niemand könnte jetzt für uns einspringen.\n\nIch möchte Euch nichts vormachen, Ihr habt selbst gesehen, wie gefährlich die Straße zum Falkenplatz sein kann, sobald man vom Dämmerweg abkommt. Fühlt Ihr Euch bereit für diese Aufgabe, {name}?", sourceObjective = "Bringt Eronas Päckchen zu Gastwirtin Delaniel im Gasthaus beim Falkenplatz im Immersangwald.", progress = "Willkommen in meinem bescheidenen Gasthaus, {class}. Ich nehme an, Ihr habt etwas für mich?", completion = "Vielen Dank, ich weiß Eure prompte Lieferung sehr zu schätzen.\n\nWo Ihr schon mal da seid, könnt Ihr es Euch auch gleich gemütlich machen. Ich habe einige Ruhesteine im Angebot, falls Ihr noch keinen erworben habt. Der Ruhestein wird dazu verwendet, um Euch an dieses Gasthaus zu binden und Euch bei Bedarf schnell dorthin zurück zu teleportieren. Macht Euch keine Sorgen, wenn Ihr Euren Ruhestein mal verlieren solltet. Kehrt einfach zu einem Gastwirt Eurer Wahl zurück und er wird Euch mit Freuden einen neuen Stein zur Verfügung stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8351] = { id = 8351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bor möchte Euch sprechen", description = "Nun, da Ihr Euch als ein führendes Mitglied des Schattenhammerklans ausgeben könnt, bin ich sicher, dass Bor Wildmähne gerne mit Euch sprechen möchte. Am besten sucht Ihr ihn gleich auf... und bereitet Euch auf eine sehr schwierige Aufgabe vor...", sourceObjective = "Sprecht mit Bor Wildmähne auf Burg Cenarius.", completion = "Ja, es stimmt, {name}. Vor uns liegt eine sehr schwere Aufgabe...", sourceObjectiveStatus = "unverified-source-field" }
quests[8352] = { id = 8352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szepter des Rates", description = "Huum und ich haben gerade über Euch gesprochen. Er erzählte mir, dass Ihr schon beinahe bereit seid, einem der abyssischen Lords entgegenzutreten!\n\nIch muss Euch warnen, das ist ein sehr gefährliches Unterfangen! Nehmt lieber Verstärkung mit, und ich meine nicht bloß ein bis zwei Eurer Freunde! Ich spreche von einer erfahrenen, kampfgestählten Truppe, die weiß, worauf sie sich einlässt. Sollten Eure Freunde aus dem gleichen Holz geschnitzt sein wie Ihr, besteht sogar eine reelle Chance, dass Ihr den Sieg davontragen werdet.\n\nFalls Ihr siegt, bringt mir wie immer einen Beweis und ich werde Euch eine wahrhaft mächtige Belohnung zuteil werden lassen.", sourceObjective = "Bringt Bor Wildmähne auf Burg Cenarius ein abyssisches Szepter.", progress = "Und, wie ist es gelaufen? Ich würde beinahe alles tun, um meinen Posten nur für einen Moment verlassen zu können, um selbst eines dieser Dinger zu erlegen!", completion = "Ihr… Ihr habt es tatsächlich geschafft! Geschafft, {name}! Dies ist die größte Truhe die wir finden konnten, und ich habe sie mit den besten Sachen gefüllt, die wir finden konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8353] = { id = 8353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnchengegacker für ein Pfefferminzbonbon", description = "Ah, wir gehen also Süßigkeitensammeln für ein krankes Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNaja, für meine Leckerei - ein Pfefferminzbonbon aus Eisenschmiede - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo {class}, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", sourceObjective = "Spielt Gastwirt Feuerbräu ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Eisenschmiede geben!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8354] = { id = 8354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnchengegacker für ein Pfefferminzbonbon", description = "Ah, wir gehen also Süßigkeitensammeln für ein krankes Kind? Ich dachte mir schon, dass Ihr etwas zu alt seid, um für Süßes loszuziehen...\n\nNaja, für meine Leckerei - ein Pfefferminzbonbon aus Unterstadt - müsst Ihr... wie ein Hühnchen gackern! Ja, Hühnchen lieben Pfefferminzbonbons... nun ja, OK, vielleicht LIEBEN sie sie nicht... aber ich gebe Euch trotzdem kein Pfefferminzbonbon, wenn Ihr nicht wie ein Hühnchen für mich gackert!\n\nSo {class}, seid Ihr dazu bereit oder nicht?! Verdient Euch Eure Süßigkeit!", sourceObjective = "Spielt Gastwirt Norman ein Huhn vor, er wird Euch dafür ein Pfefferminzbonbon aus Unterstadt geben!", progress = "Ich warte...", completion = "Was für ein Spaß! Nicht schlecht, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8355] = { id = 8355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaugummikugelexpress", description = "Ah, Süßes oder Saures! Hussah!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein krankes Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel aus Gnomeregan für das kranke Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, {class}!", sourceObjective = "Ahmt für Talvash del Kissel einen Zug nach und er wird Euch dafür eine Kaugummikugel aus Gnomeregan geben!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8356] = { id = 8356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muskelspiel für Nugat", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem kranken Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Sturmwind geben. Es ist eine großartige Schlotternachtssüßigkeit.", sourceObjective = "Ihr müsst vor Gastwirtin Allison angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Sturmwind gibt!", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, {name}...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8357] = { id = 8357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzen für Marzipan", description = "Auch wenn Ihr einem kranken Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, aber man kann...\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", sourceObjective = "Tanzt für Gastwirtin Saelienne und Ihr werdet im Gegenzug etwas von dem Marzipan aus Darnassus bekommen!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, {name}!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", sourceObjectiveStatus = "unverified-source-field" }
quests[8358] = { id = 8358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaugummikugelexpress", description = "Ah, Süßes oder Saures! Ja genau, Mann!\n\nNun, auch wenn Ihr etwas Ehrenhaftes tut und Süßigkeiten für ein krankes Kind sammelt, so kann ich Euch doch nicht so einfach davonkommen lassen. Ich hätte da eine leckere Kaugummikugel der Dunkelspeere für das kranke Kind... wenn Ihr mir einen Zug vorführt! Haha, ja, das wär's! Der Preis für diese Kaugummikugel ist das Imitieren eines Zuges!\n\nTschugga-tschugga, {class}!", sourceObjective = "Ahmt für Kali Remik einen Zug nach und sie wird Euch dafür eine Kaugummikugel der Dunkelspeere geben!", progress = "Nun, legt los...", completion = "Huu-huu! Klasse, {name}! Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[8359] = { id = 8359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muskelspiel für Nugat", description = "Das ist ein... interessantes Kostüm, welches Ihr da tragt. Auch wenn Ihr nett seid und einem kranken Kind dieses Jahr beim Süßigkeitensammeln helft, so fürchte ich doch, dass ich Euch um eine kleine Vorstellung bitten muss!\n\nMal sehen... Ihr seht in diesem... Kostüm stark und muskulös aus... jetzt gebt doch mal ein bisschen an! Ja, lasst Eure Muskeln für mich spielen, <starker Mann/starke Frau>!\n\nWenn ich Euch angeben sehe, und auch nur dann, werde ich Euch etwas von dem leckeren Nugat aus Orgrimmar geben. Es ist eine großartige Schlotternachtssüßigkeit.", sourceObjective = "Ihr müsst vor Gastwirtin Gryshka angeben, damit sie Euch im Gegenzug etwas vom Nugat aus Orgrimmar gibt!", progress = "Wenn Ihr nicht mit Euren Muskeln angeben wollt, gibt es nichts Süßes, {name}...", completion = "Ihr seid wirklich stark, haha! Gut gemacht, danke für die tolle Schau. Hier ist Eure Süßigkeit.\n\nGruselige Schlotternächte, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[8360] = { id = 8360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanzen für Marzipan", description = "Auch wenn Ihr einem kranken Kind beim Süßigkeitensammeln helft, so müsst Ihr mir noch immer etwas für Eure Belohnung vorführen! Man kann nicht so einfach mit der Tradition brechen, aber man kann...\n\nIch denke, dass ein Stück Marzipan heute eine ordentliche Tanzvorstellung wert ist! Ja genau, zeigt mal, was Ihr so drauf habt! Tanzt für mich und ich werde Euch etwas von dem leckeren Marzipan geben!", sourceObjective = "Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Donnerfels bekommen!", progress = "Ihr wisst doch wie man tanzt, oder? Rechter Fuß nach innen... dann nach außen... rechter Fuß nach innen... shake it Baby...", completion = "Ihr seid ganz schön tanzwütig, {name}!\n\nHier ist die Süßigkeit für Eure tolle Leistung. Gruselige Schlotternächte und sagt dem kranken Kindchen alles Gute von mir! Hoffentlich wird es bald wieder gesund.", sourceObjectiveStatus = "unverified-source-field" }
quests[8361] = { id = 8361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Kontakte", description = "Wir haben Kultisten des Schattenhammers dabei beobachtet, wie sie mit Hilfe bizarrer Rituale mächtige Elementarfürsten beschworen haben. Noch wissen wir nicht, ob das die Wesen sind, die die Kultisten verehren, oder ob diese Wesen nur Botschafter einer weit größeren Macht sind. Eines wissen wir jedoch mit Sicherheit: von diesen Elementaren erhält der Kult seine Befehle.\n\nIch möchte, dass Ihr versucht, mit einem abyssischen Templer Kontakt aufzunehmen. Wenn Ihr das getan habt, verpasst ihm eine ordentliche Tracht Prügel! Nichts stürzt eine Organisation so sehr ins Chaos, wie eine Unterbrechung der Befehlskette. Oh, und vergesst nicht, mir einen Beweis für Euren Erfolg zu bringen!", sourceObjective = "Bor Wildmähne auf Burg Cenarius in Silithus möchte, dass Ihr einen abyssischen Templer vernichtet und ihm dessen abyssisches Wappen als Beweis für Eure Tat bringt.", progress = "Habt Ihr Eure Aufgabe vollendet?", completion = "Hah! Ihr habt es geschafft, {name}! Schon bald werden die Twilight-Hammer besiegt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[8362] = { id = 8362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Wappen", progress = "Ihr habt Eure Fähigkeiten im Kampf mehrfach bewiesen, {name}. Wir müssen den Druck auf die Twilight-Hammer weiter aufrecht erhalten. Zieht los und bekämpft weitere abyssische Templer. Eure Mühen sollen nicht umsonst sein, und ich werde Euch mit einigen der Sachen entlohnen, die Huum und ich in der Schlacht erbeutet haben.", completion = "Ihr habt Euch hervorragend geschlagen! Und wieder einige Templer weniger, um die ich mir Sorgen machen muss.\n\nDas ist für Euch, {name}. Ich hoffe, dass Ihr einiges davon gebrauchen könnt." }
quests[8363] = { id = 8363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Siegel", progress = "Ihr habt bewiesen, dass Ihr mehr als fähig seid, es mit einem abyssischen Fürsten aufzunehmen, {name}. Ich fördere gerne jemanden, der sich als so tapfer erweist. Bringt mir mehr Siegelringe und ich werde Euch reichlich belohnen.", completion = "Sehr gut, {name}! Der Sieg über diese Fürsten, wird die Twilight-Hammer eine ganze Weile beschäftigen. Hier ist, wie versprochen, Eure Belohnung. Das sind einige der wertvolleren Gegenstände, die Huum und ich gefunden haben." }
quests[8364] = { id = 8364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssische Szepter", progress = "Ihr habt all meine Erwartungen bei weitem übertroffen, {name}. Ihr habt Euch Gegnern gestellt, bei denen Huum und ich lange und gründlichst über einen Angriff nachdenken würden.\n\nDas Beste, was ich in dieser Sache wohl tun kann, ist, Eure Bemühungen im Kampf gegen die Anhänger des Schattenhammerklans und ihre Oberanführer auch weiterhin zu belohnen.\n\nBringt mir noch mehr abyssische Szepter und ich werde mein Bestes tun, um Euch gebührend zu entlohnen.", completion = "Ich habe gewusst, dass Ihr es schaffen würdet, {name}!  Hier ist Eure Belohnung." }
quests[8365] = { id = 8365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenhüte Ahoy!", description = "Ihr seid die Hilfe, die das Kartell entsandt hat? Ach, ich denke, Ihr werdet reichen. Hört mir genau zu, {class}. Wie Ihr wisst, bin ich die Lieferantin für modische Kleidung, die in den höchsten Kreisen der Gesellschaft Azeroths gefragt ist. Könige und Königinnen, Kriegshäuptlinge und... naja wie auch immer die Horde ihre Königinnen bezeichnet, all jene tragen, was ich als modisch deklariere. Und ich verdiene mir an ihnen eine goldene Nase, was natürlich das Beste am Ganzen ist.\n\nAlso hierfür benötige ich Eure Hilfe. Lauft hinunter zur Mast- und Schotbucht und beschafft mir einen Stapel Piratenhüte, koste es was es wolle. Glaubt Ihr, Ihr schafft das, hmm?", sourceObjective = "Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin beim Dampfdruckpier in Tanaris.", progress = "Habt Ihr alle 20 Hüte? Ich glaube Euch kein Wort, zeigt sie her. Ich hoffe für Euch, dass sie noch sauber und ganz sind!", completion = "Oh, Ihr seid ein Schatz, auch wenn Ihr etwas länger gebraucht habt, als ich es gewohnt bin. Diese Lieferung wird mir so einiges an Geld einbringen, sobald ich diese Hüte richtig gesäubert und individuell gestaltet habe. Hier habt Ihr etwas für Eure Mühen, Ihr habt Eure Aufgabe mit Bravour erledigt. Ich empfehle Euch allerdings, etwas von dem Geld für ein Bad auszugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8366] = { id = 8366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaunerei und Erpressung im Südmeer", description = "Argh! Sie verlangen das Unmögliche von mir!\n\nDas Dampfdruckkartell möchte, dass ich den Südmeerpiraten eine Lektion erteile. Ich kann doch aber nicht an zwei Orten gleichzeitig sein; Ich muss hierbleiben, um zumindest hier alles ruhig zu halten.\n\nSeit neuestem hält nicht mal mehr das Schutzgeld, dass das Kartell regelmäßig auszahlt, die Piraten auf. Daher möchte ich Euch zeitweilig abordnen, mal dort runter zu gehen und denen Saures zu geben.\n\nIhr findet die Piraten in der Mast- und Schotbucht, die hier gleich in der Nähe gen Süden ist. Besten Dank, {name}, ich schulde Euch was!", sourceObjective = "Sicherheitschef Bilgenritzel beim Dampfdruckpier in Tanaris beauftragt Euch, 10 Piraten der Südmeerfreibeuter, 10 Seeräuber der Südmeerfreibeuter, 10 Dockarbeiter der Südmeerfreibeuter und 10 Schwadroneure der Südseefreibeuter zu töten.", completion = "{name}! Ihr seid der Mann!!!\n\nIch bin mir sicher, dass das Kartell mir jetzt wieder freundlicher gestimmt sein wird, nun da Ihr mir mit dem Südmeerabschaum geholfen habt. Lasst mal sehen, womit könnte ich Euch belohnen? Und wenn ich Euch ein paar Münzen gäbe, damit Ihr Euch hier etwas aussucht? Na, seid Ihr damit einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[8367] = { id = 8367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Ehre", description = "Der Horde in einer der größten Schlachten gegen die Allianz zu dienen, ist das Ausschlaggebende für große Ehre! Die Wenigen jedoch, die der Horde auf ALL unseren aktiven Schlachtfeldern gedient haben, sind unsere wahren, großen Kämpfer. Unsere Gegner sollen besiegt werden, aber nicht mittels vereinzelter Gefechte, sondern durch einen gut koordinierten Krieg.\n\nGeht und schmettert die Allianz im Arathibecken, Alteractal, Auge des Sturms und in der Kriegshymnenschlucht nieder! Für Ehre! Für die Horde!", sourceObjective = "Bringt 1 Ehrenabzeichen des Alteractals, 1 Ehrenabzeichen des Arathibeckens, 1 Ehrenabzeichen der Kriegshymnenschlucht und 1 Ehrenabzeichen vom Auge des Sturms zu einem Kriegshetzer der Horde in einer der Hauptstädte oder in Shattrath.", progress = "Arathi ist noch immer mit dem Blut großer Krieger getränkt und das Klirren von aufeinandertreffendem Stahl schallt durch das Alteractal. Verschwendet nicht meine Zeit, solange Ihr mir keine Neuigkeiten von der Front bringt!", completion = "Euer Unterfangen war nicht einfach, aber Euer Mut und Eure Stärke haben Euch nicht verlassen. Trennt Euch von alten Siegesabzeichen, {class}. Keiner soll sie als Beweis Eure Taten benötigen. Nehmt Haltung an, {name}. Heute werdet Ihr mit dem Stolz eines Helden erfüllt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[8368] = { id = 8368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen des Kriegshymnenklans zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, {name}?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8369] = { id = 8369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasoren des Alteractals", description = "Hört mir genau zu, {name}. Egal, was auch immer Ihr über die noch immer tobende Schlacht im Alteractal gehört habt, etwas davon ist wahr: Es war die Expeditionsarmee der Sturmlanzen, die diesen Konflikt durch die Besetzung des Territoriums der Frostwölfe entfachte. Der Tag, an dem wir es der Allianz erlauben, Gebiete der Horde zu erobern, ohne militärisch zurückzuschlagen, wird der Tag sein, an dem ich meine Axt an den Nagel hänge, um den Rest meines Lebens in Schande zu verbringen. Geht jetzt und schlagt die Invasoren zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Habt Ihr Neuigkeiten aus dem Lande der Frostwolf? Wie läuft die Schlacht im Alteractal?", completion = "Durch die Verteidigung unserer Ländereien im Alteractal habt Ihr Euren Mut bewiesen! Ich werde meinen Vorgesetzten von Euren Bemühungen berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8370] = { id = 8370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens", description = "Unser Konflikt mit der Allianz hat sich zu einem richtigen Krieg entwickelt. Es ist nicht länger notwendig unter falschen Vorwänden in die Schlacht zu ziehen, keine Seite erwartet dies noch länger.\n\n In der Schlacht um das Arathibecken geht es nur um eines, Ressourcen. Nicht mehr und nicht weniger. Entweder die Allianz erobert diese Ressourcen und benutzt sie gegen uns, oder wir kommen ihnen zuvor und verwenden die dortigen Ressourcenquellen für unsere Kriegspläne. {name}, helft den Entweihten dabei, die von uns benötigten Ressourcenlieferungen aufrecht zu erhalten!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Habt Ihr Neuigkeiten aus dem Arathibecken, {name}?", completion = "Die Sicherung unserer Ressourcen im Arathibecken ist eine lebenswichtige Aufgabe! Ihr habt sie gut gemeistert, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8371] = { id = 8371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsames Bestreben", description = "Wir kämpfen nicht mehr in vereinzelten Schlachten gegen die Horde, <Junge/Mädchen>.\n\nDer gesamte Sieg an einer Front bedeutet der Horde die Ressourcen abzusprechen, die sie ansonsten in einer anderen Schlacht gegen uns verwenden würden. Ebenso könnte das Aufgeben in was auch immer für einer Schlacht unserem Gegner andernorts in der Welt einen Vorteil verschaffen.\n\nDie Allianz benötigt mehr Kämpfer mit diesem globalen Verständnis... wirklich bewährte Veteranen! {name}, kommt zu mir zurück, wenn Ihr Euch gegen die Horde auf all unseren aktiven Schlachtfeldern bewährt habt.", sourceObjective = "Bringt 1 Ehrenabzeichen des Alteractals, 1 Ehrenabzeichen des Arathibeckens, 1 Ehrenabzeichen der Kriegshymnenschlucht und 1 Ehrenabzeichen vom Auge des Sturms zu einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", progress = "Wie geht's voran, Bursche?", completion = "Ihr habt nicht enttäuscht, {name}! Was Ihr gelernt habt, geht über unbedeutende Medaillen und Auszeichnungen hinaus. Was Ihr gelernt habt, erlangt man nur durch Erfahrung und Abhärtung auf dem Schlachtfeld.\n\nIhr habt Euch gut geschlagen, {class}. Ihr seid ein wahrer Held der Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[8372] = { id = 8372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um die Kriegshymnenschlucht", description = "Die Schildwachen der Silberschwingen sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Vorhut des Kriegshymnenklans. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, das Eschental gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Vorhut des Kriegshymnenklans, {name}! Für die Allianz!", sourceObjective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, {name}?", completion = "Gut gemacht, {name}! Ihr habt viel für die Allianz geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8373] = { id = 8373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft der Pinie", description = "Was ich während der Schlotternächte am meisten hasse, sind die Stinkbomben, die die Verlassenen hier inmitten von Süderstade loslassen. Wer hätte gedacht, dass eine Gedenkfeier zur Freilassung mit einer so stinkigen Sache einhergehen würde?\n\nVerwendet diesen Stinkbombenreiniger während der Schlotternächte, um die scheußlichen Stinkbomben, die die Horde womöglich hier in der Stadt loslässt, zu vernichten. Er bekämpft, dank der Kraft von Pinien, schreckliche Gerüche.\n\nHelft mit Süderstade sauber zu halten und ich werde Euch dafür ein paar Schlotternachtssüßigkeiten geben, die Ihr sicherlich mögen werdet. Abgemacht?", sourceObjective = "Verwendet einen Stinkbombenreiniger, um alle Stinkbomben der Verlassenen zu vernichten, die hier in Süderstade losgelassen wurden. Kehrt zu Unteroffizier Hartman in Süderstade zurück, wenn Ihr fertig seid.", completion = "Ah, es riecht schon fast wieder gut hier. Fast.\n\nIch danke Euch, {name}, Southshore kommt vielleicht ein weiteres Mal über die Schlotternächte hinweg. Hier sind Eure Süßigkeiten, gern geschehen! Solltet Ihr noch mehr Süßigkeiten benötigen, dann könnte Euch eventuell eine Gnomin namens Katrina Shimmerstar in Ironforge noch mehr verkaufen; ich glaube, dass sie sich nur während der Schlotternächte dort aufhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[8374] = { id = 8374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inbesitznahme des Arathibeckens", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8375] = { id = 8375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst das Alteractal nicht!", description = "Ihr liegt vollkommen richtig, {name}. Die Horde verkündet die Wahrheit, mit ihrer Behauptung, das Alteractal gehöre zum Territorium der Frostwölfe. Die Sturmlanzen kamen, auf der Suche nach Erzvorkommen und Relikten, mit friedlichen Absichten in das Tal. Die Frostwölfe jedoch, reagierten auf die Anwesenheit der Sturmlanzen mit einer, in der Allianz, bis dato unbekannten Brutalität und Aggressivität.\n\nNiemals dürfen wir all die Zwerge vergessen, die während des folgenden feigen und unangekündigten Angriffs zu Tode kamen. Geht nun, {name}, und tragt Euren Teil zur Schlacht im Alteractal bei. Für die Allianz!", sourceObjective = "Bringt 3 Ehrenabzeichen des Alteractals zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", progress = "Habt Ihr Neuigkeiten, {name}?", completion = "Ihr habt Euren Beitrag geleistet, {name}! Die Allianz wird den barbarischen Ausschreitungen der Horde nicht tatenlos gegenüber stehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8376] = { id = 8376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese... diese Prophezeiung jemals wahr werden...\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8377] = { id = 8377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
