quests[8381] = { id = 8381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8382] = { id = 8382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsausrüstung", sourceObjective = "Ein Krieg wird kommen, {name}, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[8383] = { id = 8383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst das Alteractal nicht!", progress = "Die Schlacht im Alteractal tobt noch immer, {name}! Habt Ihr schon Euren Teil zum Sieg beigetragen, {name}?", completion = "Wieder einmal ehrt Ihr die Allianz, {name}! Wenn wir so weiter machen, wird es nicht mehr lange dauern, bis die Horde vernichtet ist." }
quests[8384] = { id = 8384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inbesitznahme des Arathibeckens" }
quests[8385] = { id = 8385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsames Bestreben", progress = "Ah, {name}. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf.", completion = "Ihr werdet Eurem Ruf gerecht, {name}. Ohne Kämpfer wie Euch, würde die Allianz keine Chance gegen die barbarischen Streitkräfte der Horde haben." }
quests[8386] = { id = 8386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um die Kriegshymnenschlucht" }
quests[8387] = { id = 8387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasoren des Alteractals", progress = "Die Schlacht im Alteractal tobt noch immer, {name}! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben.", completion = "Gute Arbeit, {name}! Ihr könnt stolz auf Euch sein. Die Invasoren der Allianz müssen aus dem Alteractal getrieben werden, koste es, was es wolle!" }
quests[8388] = { id = 8388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Ehre", progress = "Viele mutige Kämpfer sehen zu Euch auf, {name}. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?", completion = "Ihr ehrt die Horde auch weiterhin, {name}. Ich freue mich zu sehen, dass Ihr nicht nachgebt." }
quests[8389] = { id = 8389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", progress = "Der Kampf um die Warsongschlucht geht weiter, {name}. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", completion = "Gut gemacht, {class}! Ihr habt der Horde geholfen ihr Eigentumsrecht an der Warsongschlucht zu sichern!" }
quests[8390] = { id = 8390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberung des Arathibeckens" }
quests[8391] = { id = 8391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inbesitznahme des Arathibeckens", progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, {name}. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, {class}. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen." }
quests[8392] = { id = 8392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inbesitznahme des Arathibeckens", progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, {name}. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, {class}. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen." }
quests[8393] = { id = 8393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inbesitznahme des Arathibeckens", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", sourceObjective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", sourceObjectiveStatus = "unverified-source-field" }
