quests[8404] = { id = 8404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um die Kriegshymnenschlucht", progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, {name}?", completion = "Gute Arbeit, {name}. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen." }
