quests[8408] = { id = 8408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um die Kriegshymnenschlucht", progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, {name}?", completion = "Gute Arbeit, {name}. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen." }
quests[8409] = { id = 8409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorbenes Bier", description = "Die faulen Eier wurden wie geplant in den Braukessel geworfen. Zukünftige Ladungen Bier des Gasthauses von Süderstade sind somit erfolgreich verdorben worden!\n\nIhr solltet jetzt zurück zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal gehen und ihr von Eurem Erfolg berichten.", sourceObjective = "Kehrt zur Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", completion = "Ah, Erfolg! Ihr habt wahren Schlotternachtsgeist bewiesen - Geist eines VERLASSENEN sollte ich wohl eher sagen!\n\n<Ruferin der Dunkelheit Yanka lacht und reibt sich die Hände.>\n\nIch lache mir ins Fäustchen, dass Southshore sich jetzt an verdorbenem Bier erfeuen darf! Hier habt Ihr Eure Süßigkeiten. Ich bin mir sicher, dass Ihr eine gute Verwendung dafür finden werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[8410] = { id = 8410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarbeherrschung", description = "Bath'rah der Windbehüter sucht nach einem Schamanen von Eurer Weisheit. Als Zeichen Eurer Bereitschaft bittet er Euch, ihm Proben eines jeden Elements zu bringen.\n\nUm Bath'rah zu finden, begebt Euch zu dem Fluss östlich von Tarrens Mühle. Folgt seinem Verlauf Richtung Norden, irgendwann trefft Ihr auf die Ruinen, in denen sich Bath'rah niedergelassen hat.", sourceObjective = "Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt.", progress = "Was habt Ihr mir mitgebracht, {class}?", completion = "Hey, gut gemacht. Unterhalten wir uns jetzt…", sourceObjectiveStatus = "unverified-source-field" }
quests[8411] = { id = 8411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beherrschung der Elemente", description = "Willkommen, {class}. Bringt mir zuerst die Elemente und dann unterhalten wir uns.\n\nIch brauche erst das Feuer, die Luft, das Wasser und die Erde, bevor ich Euch vertraue, Mann. Ich muss wissen, ob Ihr gut unterrichtet seid.", sourceObjective = "Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[8412] = { id = 8412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistertotem", description = "Die Elementare an diesem Ort haben sich gegen mich gewendet.\n\nIhr kennt Euch mit den Mächten der Totems besser als jeder andere aus und ich brauche jetzt ein Geistertotem zu meinem Schutz. Wir haben bereits die Elemente, jetzt brauchen wir etwas mit noch mehr Natur. Etwas noch Wilderes.\n\nIn den westlichen Pestländern könnt Ihr Bären für Klauen und Spinnen für Augen töten. Mit etwas Glück, könnt Ihr beides auch bei den dort lebenden Aasgeiern finden, sie fressen alles.", sourceObjective = "Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.", progress = "Die Geister wissen, was wir vorhaben und haben versucht, mich zu töten! Ich hoffe Ihr habt die Komponenten.", completion = "Gut, mein Freund! Versuchen wir es…", sourceObjectiveStatus = "unverified-source-field" }
quests[8413] = { id = 8413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Voodoos", description = "Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.\n\nDie Trolle im Versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit Ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.", sourceObjective = "Bringt Bath'rah dem Windbehüter die Voodoofedern.", progress = "Wo sind die Federn, mein Freund?", completion = "Es ist Zeit, dass dieser Troll eine ganze Nacht Ruhe bekommt! Das Geistertotem wird über mich wachen\n\nIch habe eine ganze Weile Dinge gesammelt, vielleicht möchtet Ihr ja was für all' Eure Mühe?", sourceObjectiveStatus = "unverified-source-field" }
quests[8414] = { id = 8414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Austreibung des Bösen", description = "Seid gegrüßt, {class}. Kreuzfahrer wie Ihr werden in solch abgeschiedenen Gegenden gerne gesehen.\n\nEure heilige Stärke wird gebraucht, um uns bei der Vernichtung der unzähligen Untoten hier zu helfen. Genau genommen bräuchten wir Euch, um eine große Anzahl von Geißelsteinen zu sammeln und sie anschließend zu Hohepriester Thel'danis zu bringen. Der Hohepriester bewacht Uthers Grabmal in Trauerhügel, nicht weit von hier.\n\nNur jemand mit einer Anstecknadel der Argentumdämmerung kann darauf hoffen Geißelsteine zu finden, sprecht also mit Offizier Reinherz, wenn Ihr noch keine besitzt.", sourceObjective = "Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern.", progress = "Habt Ihr mir Böses gebracht?", completion = "Es ist ein Risiko Böses aus einem Geißelstein zu treiben, da es die Aufmerksamkeit von Untoten bis auf unzählige Kilometer erweckt. Ihr seid jedoch stark im Licht, {name}, und ich sorge mich nicht um Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[8415] = { id = 8415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zugwindlager", description = "Kommandant Ashlam Ehrenschlag sucht nach einem Paladin Euer Reinheit und Euren Mutes, {name}. Ihr könnt ihn im Zugwindlager im Süden der westlichen Pestländer finden. Sucht nach ihm und helft ihm im Namen des Lichts!", sourceObjective = "Sprecht mit Kommandant Ashlam Ehrenschlag im Zugwindlager.", completion = "Na dann, {class}! Jetzt zeigt mal, was Ihr könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8416] = { id = 8416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gereinigte Geißelsteine", description = "Das Böse wurde aus diesen Steinen getrieben, {name}.\n\nIch weiß über Kommandant Ashlams Pläne Bescheid, er wird nur nach einem einzigen, gereinigten Geißelstein verlangen. Bringt ihn zu ihm, damit wir die Geißel ins Feuer der Gerechtigkeit tauchen können.", sourceObjective = "Bringt den gereinigten Geißelstein zu Kommandant Ashlan Ehrenschlag an der Zugwindspitze.", progress = "Konnte Thel'danis die Geißelsteine reinigen?", completion = "Ihr habt meine Befehle ohne weiteres Fragen befolgt, {name}.\n\nIhr scheint Vertrauen bewiesen zu haben. Vielleicht kann ich Euch jetzt mehr über unsere Pläne verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8417] = { id = 8417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geplagter Geist", description = "In den verwüsteten Landen gibt es einen geplagten Geist, der einst ein großer Held der Horde war. Die Ehre eines Kriegers stirbt nicht mit seinem Körper und es würde für Euch von Wert sein mit ihm zu sprechen.", sourceObjective = "Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen.", completion = "So, Ihr seid also gekommen um meinen Schmerz zu lindern. Ich wünschte, Ihr könntet mich einfach niederstrecken, aber es ist nicht so simpel...", sourceObjectiveStatus = "unverified-source-field" }
quests[8418] = { id = 8418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschaffung des Steins der Macht", description = "Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, {name}. Nur die Trolle des Versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.\n\nIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... sie sind nicht frei von Bösem.", sourceObjective = "Bringt die Voodoofedern zu Ashlam Ehrenschlag.", progress = "Habt Ihr die elenden Trolle getötet?", completion = "Das ist ausgezeichnet, {name}. Ich könnte sagen, dass ich überrascht bin, allerdings habe nicht daran gezweifelt, dass Ihr uns nicht enttäuschen werdet.\n\nEs ist mir eine Ehre Euch einen der heiligen Steine der Macht zu überreichen. Verwendet ihn weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[8419] = { id = 8419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte eines Wichtels", description = "{name}, ein Wichtel im Teufelswald namens Impsy hat nach Euch verlangt. Seine Bitte ist etwas merkwürdig, da er möchte, dass Ihr ihm ein Stück Teufelsstoff als Zeichen des \"guten Willens\" bringt. Bedenkt man die Macht, die Ihr bereits als Hexenmeister besitzt, kann ich nur vermuten, dass Ihr wisst, dass die Satyrn des Teufelswalds diesen Teufelsstoff bei sich tragen.\n\nIhr findet Impsy nördlich der Blutgiftfälle, von denen ich hörte, dass sie um diese Jahreszeit recht schön sein sollen.", sourceObjective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", progress = "Habt Ihr den Teufelsstoff?", completion = "Ah, wie großartig Ihr doch seid!\n\n<Impsy drückt den Teufelsstoff an sein Gesicht.>\n\nOh, wie sehr ich dieses Gefühl liebe, dieses sanfte Brennen auf der Haut und diese Wallungen des Bösen, die durch den Geist huschen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8420] = { id = 8420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiß und brennend", description = "Vielleicht klingt es ja etwas komisch bei einem Wichtel, aber ich würde gerne meinen eigenen Begleiter haben. Das hätte ich wirklich gerne. Es ist nicht fair, dass Niby mich hat und ich niemanden!\n\nEs braucht ja gar nicht lebendig zu sein. Ich bräuchte etwas, um mit der Anfertigung beginnen zu können, zum Beispiel etwas Teufelsstoff. Die Satyrn hier im Teufelswald haben manchmal Teufelsstoff, Ihr müsstet also nur genug von ihnen töten, um welchen zu finden. Das hört sich doch gut an, oder?", sourceObjective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", progress = "Habt Ihr den Teufelsstoff?", completion = "Wow! Ihr seid wirklich total freundlich. Besonders für einen {class}!\n\n\n\nOh, wie sehr ich dieses Gefühl liebe, dieses sanfte Brennen auf der Haut und diese Wallungen des Bösen, die durch den Geist huschen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8421] = { id = 8421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Zeug", description = "Jetzt, da ich meinen Teufelsstoff habe, kann ich wirklich mit der Anfertigung *meines* Begleiters beginnen.\n\nIch werde etwas für die Augen brauchen. Vielleicht könnt Ihr mir etwas faules Holz vom Stamm der Eisenstämme besorgen, damit ich daraus ein Paar wunderschöne Augen schnitzen kann. Ihr findet sie im Norden, im Eisenwald.\n\nIch brauche auch etwas Blutgiftessenz, um meinem Begleiter diesen neuen dämonischen Duft zu verleihen. Die besudelten Brühschlammer haben diese Essenz und Ihr könnt sie gleich hier in der Nähe von Niby und mir finden.", sourceObjective = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.", progress = "Habt Ihr das Zeug?", completion = "Dies wird seinen Zweck bestens erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8422] = { id = 8422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn von Trollen", description = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.\n\nNur die Voodoofedern von den Trollen aus dem Versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.\n\nDies ist keine gewöhnliche Aufgabe {name}, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe -- er wird es sowieso nicht mehr brauchen.", sourceObjective = "Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel.", progress = "Habt Ihr die Federn? Mein Begleiter braucht eine Füllung!", completion = "Wunderbar, jetzt ist mein Begleiter komplett!\n\n<Impsy stopft die Puppe schnell aus und umarmt sie auf dämonische Weise.>\n\nOh, was für einen merwürdigen Nebeneffekt diese Voodoofedern doch haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[8423] = { id = 8423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegerverwandtschaft", description = "<Der Held betrachtet Euch.>\n\nIhr seid ein {class}, ohne Zweifel. Ich würde Euch um eine ehrenhafte Aufgabe bitten, aber zuerst muss ich Eure Stärke testen.\n\nMan sagt, dass Rexxar die Schärfe seiner Klingen misst, indem er einen Hölleneber mit nur einem einzigen, schnellen Schlag erlegt. Jetzt werde ich Eure Stärke auf die gleiche Art messen.", sourceObjective = "Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", completion = "Ich brauche keinen Beweis für Eure Taten, {class}. Ich kann es an dem entschlossenen Ausdruck in Eurem Gesicht erkennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8424] = { id = 8424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg den Schattenanbetern", description = "Die weiterhin bestehende Gegenwart der Schattenanbeter in den verwüsteten Landen ist schmerzhaft für mich. Ihre dunklen Rituale und Zauber bereiten mir heute mehr Qualen als es zu meinen Lebzeiten je etwas hätte tun können.\n\nIch kann ihnen mit Eurer Hilfe eine schmerzhafte Botschaft überbringen. Zieht hinfort und lasst meinen Zorn sprechen.", sourceObjective = "Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", progress = "Die Schattenanbeter lassen sich nicht so leicht unterkriegen, nicht wahr? Ihr seid jedoch ein {class} und werdet entweder triumphieren oder zumindest bei dem Versuch sterben.", completion = "Ihr habt meinen Schmerz bereits überwältigt und mich geehrt. Ich danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8425] = { id = 8425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoofedern", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zu dem Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neu bilden können, damit ich Euch belohnen kann.", sourceObjective = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde.", progress = "Seid Ihr schon zurück? Zeit ist für mich nicht mehr, was sie einst für mich war, vielleicht habt Ihr ja wirklich schon einen langen Ausflug hinter Euch...", completion = "Endlich kann ich die kalte Berührung von Stahl wieder spüren, auch wenn es nur für einen Moment ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8426] = { id = 8426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, {name}?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8427] = { id = 8427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, {name}?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8428] = { id = 8428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, {name}! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", sourceObjective = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", sourceObjectiveStatus = "unverified-source-field" }
